/* Group G04 mastery bank: The self (optional); Perception (optional). Original questions, not copied from past papers. */
(function () {
  'use strict';
  var B = window.MASTERY_BANKS = window.MASTERY_BANKS || {};
  // M: single-answer item, the correct option is listed first (the engine shuffles the options).
  function M(skill, q, right, wrongs, why, extra) {
    var it = { skill: skill, kind: 'mcq', q: q, options: [right].concat(wrongs), answer: 0, why: why };
    if (extra) for (var k in extra) it[k] = extra[k];
    return it;
  }
  // X: select-all item, the correct options are listed first.
  function X(skill, q, rights, wrongs, why, extra) {
    var it = { skill: skill, kind: 'multi', q: q, options: rights.concat(wrongs), answers: rights.map(function (_, i) { return i; }), why: why };
    if (extra) for (var k in extra) it[k] = extra[k];
    return it;
  }

  /* ---------- PSY-SLF-03 Maslow ---------- */
  B['PSY-SLF-03'] = { title: "Maslow's hierarchy of needs", items: [
    M('Levels and order', "In Maslow’s (1943) hierarchy of needs, which need sits directly above safety needs?",
      "Love and belonging", ["Esteem", "Physiological needs", "Self-actualisation"],
      "From the bottom the order is physiological, safety, love and belonging, esteem, then self-actualisation. Love and belonging comes straight after safety."),
    M('Levels and order', "Which list shows Maslow’s needs in the correct order, from the bottom of the hierarchy to the top?",
      "Physiological, safety, love and belonging, esteem, self-actualisation",
      ["Safety, physiological, love and belonging, esteem, self-actualisation", "Physiological, safety, esteem, love and belonging, self-actualisation", "Physiological, love and belonging, safety, self-actualisation, esteem"],
      "The base is physiological needs and the top is self-actualisation. Esteem comes after love and belonging, not before it."),
    M('Levels and order', "Which need forms the base of Maslow’s hierarchy?",
      "Physiological needs such as food and sleep", ["Safety needs such as shelter and a secure job", "Love and belonging needs such as friendship", "Esteem needs such as respect from others"],
      "Physiological needs (food, water, warmth, sleep) are the most basic, so they form the base that the other levels are built on."),
    M('Levels and order', "Maslow’s hierarchy is usually drawn as which shape?",
      "A pyramid, with basic needs at the bottom", ["A circle, with all needs equally important", "A ladder with the top need at the base", "A pyramid, with self-actualisation at the base"],
      "Maslow (1943) arranged needs in a hierarchy, usually drawn as a pyramid with basic needs at the bottom and self-actualisation at the top."),
    M('Deficiency and growth needs', "Which statement about Maslow’s levels is correct?",
      "Self-actualisation is a growth need; the four lower levels are deficiency needs", ["Self-actualisation is a deficiency need; the four lower levels are growth needs", "All five levels are deficiency needs", "Only physiological needs are deficiency needs"],
      "The lower four levels (physiological, safety, love and belonging, esteem) are deficiency needs. Self-actualisation is the growth need, about becoming all you can be."),
    X('Deficiency and growth needs', "Which of these are deficiency needs in Maslow’s hierarchy?",
      ["Physiological needs", "Safety needs", "Esteem needs"], ["Self-actualisation", "A need to win every competition"],
      "Physiological, safety, love and belonging and esteem are all deficiency needs. Self-actualisation is the growth need, and winning every competition is not a level in the hierarchy."),
    M('Deficiency and growth needs', "In Maslow’s theory, what does ‘self-actualisation’ mean?",
      "Becoming everything you are capable of being", ["Having enough food, water, warmth and sleep", "Feeling safe in a secure home and job", "Being respected by other people at work"],
      "Self-actualisation is the highest need: reaching your full potential and becoming everything you are capable of being."),
    M('The hierarchy rule', "Which statement best sums up Maslow’s rule about how needs work?",
      "Lower needs must largely be met before higher needs motivate us", ["Higher needs must be met first, and only then the lower needs", "All five needs motivate a person equally at all times of life", "Only one need in the hierarchy ever matters to any person"],
      "Maslow said people are mainly motivated by the lowest level that is not yet met. Once lower needs are largely met, higher needs start to motivate behaviour."),
    M('Application: unmet need', "Aisha has been sleeping on a friend’s sofa since losing her flat. She no longer goes to her painting class and cannot concentrate on her art. Using Maslow, which need is most likely unmet?",
      "Safety (shelter and security)", ["Self-actualisation (reaching her full potential)", "Esteem (respect and recognition)", "Love and belonging (friendship)"],
      "Having no home of her own is a threat to safety needs (shelter, security). Because safety is not met, she is not motivated by a higher need like developing her painting."),
    M('Application: unmet need', "Marco has moved to a new city. He eats well, has a safe flat and a steady job, but knows nobody and feels lonely. He has stopped bothering to improve at his hobbies. Which level of need is Marco struggling to meet?",
      "Love and belonging", ["Physiological needs", "Safety needs", "Self-actualisation"],
      "His food and shelter are secure, so the unmet need is love and belonging (friendship and connection). Under Maslow, this stops him being motivated by higher needs like self-improvement."),
    M('Application: unmet need', "Priya is a nurse with a secure job, a loving family and good friends. She feels her hard work is never recognised, so she keeps asking for promotion and praise. Which need is she trying to meet?",
      "Esteem", ["Safety", "Physiological needs", "Self-actualisation"],
      "Her lower needs are already met. Wanting recognition, status and praise from others is an esteem need, the level above love and belonging."),
    M('Application: unmet need', "Walt is a retired teacher with a comfortable home, close family and plenty of respect in his town. He now spends every morning composing music because he wants to see how good he can become. Which need is Walt pursuing?",
      "Self-actualisation", ["Esteem", "Love and belonging", "Safety"],
      "With the four deficiency needs largely met, Walt is working towards his full potential. This is self-actualisation, the growth need at the top of the hierarchy."),
    M('Application: hierarchy rule', "A teacher notices that Jo arrives at school every day without breakfast and cannot concentrate on lessons. Which explanation uses Maslow’s hierarchy correctly?",
      "Jo’s physiological need for food is unmet, so learning is not what motivates him", ["Jo’s need for self-actualisation is met, so he has stopped trying to learn", "Jo’s esteem needs must be met before he can feel any hunger at all", "Hunger is a growth need, so it does not affect his learning"],
      "Food is a physiological need at the base of the hierarchy. Until it is largely met, higher goals such as learning are not the main motivation."),
    M('Application: hierarchy rule', "Stefan’s factory has closed and he cannot pay his rent. He has stopped going to band practice. Which answer gives the best Maslow explanation?",
      "His safety needs (income and shelter) are unmet, so he is not motivated by a higher need like his music", ["His physiological need for music is unmet, so he cannot go to band practice", "His esteem needs are fully met, so he no longer needs the band at all", "His self-actualisation is now complete, so he can simply stop practising"],
      "A full answer names the unmet level (safety), states the hierarchy rule (lower needs come first) and links it to the behaviour (giving up band practice)."),
    M('Application: hierarchy rule', "Which is the best-developed explanation of why Hana, who has no steady income, is not interested in a night course?",
      "Her safety need for financial security is unmet, and lower needs must be met before she is motivated by growth", ["She has a safety need and so wants the night course", "Night courses are an esteem need so she does not want one", "Maslow said that income does not affect motivation at all"],
      "Credit comes from naming the unmet need, stating Maslow’s rule about lower needs coming first, and linking this to Hana’s lack of interest in the course."),
    X('Levels and order', "Which of these are examples of safety needs?",
      ["A permanent job contract", "A secure, lockable home"], ["Close friendships", "Praise and respect from colleagues", "Food and water"],
      "Safety needs cover security, shelter and employment. Friendships are love and belonging, respect is esteem, and food and water are physiological."),
    X('Levels and order', "Which of these are physiological needs?",
      ["Water", "Sleep", "Warmth"], ["Friendship", "A promotion at work"],
      "Physiological needs are the body’s basic requirements: food, water, warmth and sleep. Friendship is love and belonging; a promotion relates to esteem."),
    M('Levels and order', "A footballer is delighted when fans chant his name and the manager praises his skill. Which level of need is being met?",
      "Esteem", ["Love and belonging", "Self-actualisation", "Physiological needs"],
      "Respect, status, recognition and praise are esteem needs. Love and belonging is about friendship, family and affection."),
    M('Evaluation', "Which is a genuine weakness of Maslow’s hierarchy of needs?",
      "People can pursue higher needs, such as art, even when lower needs are unmet", ["It was tested using mainly laboratory experiments on animals", "It cannot explain any human behaviour or motivation at all", "It says that safety needs sit above esteem needs in the order"],
      "The strict order may be too rigid because some people chase creative or social goals while hungry or poor. The other options are not true of the theory."),
    M('Evaluation', "A homeless artist keeps painting every day even though she is often hungry. What does this suggest about Maslow’s hierarchy?",
      "The strict order of needs may not be true for everyone", ["The hierarchy has been proved correct for absolutely everyone", "Physiological needs are really growth needs not deficiency needs", "Safety needs always come before physiological needs in the order"],
      "She is pursuing a high-level need (creativity) while lower needs are unmet. This challenges the idea that lower needs must always be met first."),
    M('Evaluation', "Which is a strength of Maslow’s hierarchy of needs?",
      "It helps carers and teachers understand why people lack motivation when basic needs are not met", ["It has been proved correct by many controlled experiments", "It shows that every person follows exactly the same life path", "It measures each need with a precise numerical score for each person"],
      "A strength is that the theory is useful in practice, for example in education and care, where it explains how unmet basic needs affect motivation. It is hard to test, so it is not proved."),
    M('Evaluation', "Which is a weakness of Maslow’s hierarchy that makes it difficult to test scientifically?",
      "Concepts like self-actualisation are hard to measure", ["It has been tested many times and every result matched it exactly", "It was based on far too many participants to be useful", "It does not mention any levels of need in the pyramid"],
      "Needs such as self-actualisation are abstract and hard to define or measure, so the theory is hard to test."),
    M('Neighbouring ideas', "Which of these ideas does NOT belong to Maslow’s hierarchy of needs?",
      "Conditions of worth", ["Esteem needs", "Deficiency needs", "Self-actualisation"],
      "Conditions of worth belong to Rogers’ humanistic theory of the self, not to Maslow’s hierarchy.")
  ] };

  /* ---------- PSY-SLF-01 Self-concept ---------- */
  B['PSY-SLF-01'] = { title: 'Self-concept: who you think you are', items: [
    M('Lewis: existential and categorical self', "According to Lewis (1990), what is the existential self?",
      "The first awareness that you exist as separate from other people and objects", ["Describing yourself using categories such as age and gender", "How much you value and like yourself as a person", "The person you would like to be in the future"],
      "The existential self is the earliest part of self-concept, in infancy: knowing that you exist and are separate from others. Describing yourself by categories is the categorical self."),
    M('Lewis: existential and categorical self', "According to Lewis (1990), what is the categorical self?",
      "Describing yourself using categories such as age, gender, size or skills", ["Knowing you exist separately from other people", "Matching your ideal self and your self-image closely", "Valuing yourself highly and feeling proud of who you are"],
      "After the existential self, children develop the categorical self: they place themselves in categories such as age, gender, size and skills."),
    M('Lewis: existential and categorical self', "Nine-month-old Lina discovers that when she kicks her legs the mobile above her cot moves, and she keeps doing it to make it move. Which part of self-concept is she developing?",
      "The existential self", ["The categorical self", "Congruence", "Her ideal self"],
      "She is becoming aware that she exists separately from the mobile and can act on it. This early awareness of being a separate person is the existential self."),
    M('Lewis: existential and categorical self', "Four-year-old Ravi says, ‘I am a boy, I am tall, and I can ride a scooter.’ Which part of his self-concept is shown?",
      "The categorical self", ["The existential self", "Incongruence", "Self-actualisation"],
      "Ravi describes himself by gender, size and skill. Describing yourself using categories like these is the categorical self."),
    M('Lewis: existential and categorical self', "In Lewis’s account, which develops first?",
      "The existential self, followed by the categorical self", ["The categorical self, followed by the existential self", "Both appear at exactly the same time", "Self-image, followed by the existential self"],
      "Lewis said the existential self comes first (awareness of existing separately) and the categorical self comes next (describing yourself by categories)."),
    X('Lewis: existential and categorical self', "Which of these are examples of the categorical self?",
      ["‘I am seven years old.’", "‘I am a girl.’", "‘I am good at swimming.’"], ["‘I know I am a separate person from my mum.’", "‘I wish I were famous.’"],
      "Age, gender and skills are categories used to describe yourself. Knowing you are separate from others is the existential self, and wishing to be famous relates to the ideal self."),
    M('Key terms', "What is meant by ‘self-esteem’?",
      "How much you value or like yourself", ["How you see yourself, including looks and abilities", "The person you would like to be", "Knowing that you exist"],
      "Self-esteem is about how much you value yourself. How you see yourself is self-image."),
    M('Key terms', "Zainab thinks of herself as shy, good at science and a bit clumsy. Which term describes this?",
      "Her self-image", ["Her self-esteem", "Her ideal self", "Her conditions of worth"],
      "Self-image is how you see yourself (looks, abilities, personality). Zainab is describing how she sees herself, not how much she values herself."),
    M('Key terms', "Dev does not like himself much and often says he is ‘not worth anything’. Which term describes this?",
      "Low self-esteem", ["A strong ideal self", "A high self-image", "Congruence"],
      "How much a person values themselves is self-esteem. Dev values himself little, so he has low self-esteem."),
    M('Key terms', "What does Rogers mean by a person’s ‘ideal self’?",
      "The person they would like to be", ["The person they believe they are now", "The person other people say they are", "The person they were as a child"],
      "The ideal self is the person you would like to be. The self-image is the person you think you are."),
    X('Key terms', "Which of these statements describe someone’s self-image?",
      ["‘I think I am quite good at maths.’", "‘I see myself as a funny person.’"], ["‘I wish I were braver.’", "‘I would love to be a team leader one day.’", "‘I like myself a lot.’"],
      "Self-image is how you see yourself now. Wishes about who you would like to be describe the ideal self, and liking yourself is self-esteem."),
    M('Congruence and incongruence', "Rogers said a person is ‘congruent’ when…",
      "their self-image and ideal self closely match", ["their self-image and ideal self are very different", "they have no ideal self at all", "other people agree with everything they do"],
      "Congruence means the self-image and ideal self fit together. Incongruence is when they do not."),
    M('Congruence and incongruence', "Hugo wants to be a fast, confident sprinter and team captain. He sees himself as slow and nervous in races. According to Rogers, Hugo is…",
      "incongruent, because his self-image does not match his ideal self", ["congruent, because he has an ideal self as a sprinter", "congruent, because he is nervous in races", "incongruent, because he is a sprinter and a captain"],
      "There is a big gap between how Hugo sees himself (slow, nervous) and who he wants to be (fast, confident). This mismatch is incongruence."),
    M('Congruence and incongruence', "Mina wants to be a caring and organised nurse. She sees herself as caring and organised. What does Rogers’ theory predict about Mina?",
      "She is congruent, so she is likely to have higher self-esteem", ["She is incongruent, so her self-esteem will be low", "She is categorical, so she cannot be congruent at all", "She has no self-image because she has an ideal self"],
      "Her self-image and ideal self match, which is congruence. Rogers linked congruence with higher self-esteem."),
    M('Congruence and incongruence', "According to Rogers, what is a likely effect of incongruence?",
      "Lower self-esteem", ["Higher self-esteem", "A stronger existential self", "No change to how someone feels"],
      "When the self-image falls short of the ideal self, people feel they are not who they want to be, which lowers self-esteem."),
    M('Congruence and incongruence', "Ravi wants to be popular and outgoing but sees himself as quiet and awkward. Which describes what is happening?",
      "A gap between self-image and ideal self is likely to lower his self-esteem", ["His self-image and ideal self match, so his self-esteem is high", "He has not yet developed an existential self at all", "He is using categories to describe himself, which is incongruence"],
      "The mismatch between the self he sees (quiet, awkward) and the self he wants to be (popular, outgoing) is incongruence, which tends to lower self-esteem."),
    M('Congruence and incongruence', "Which change would be most likely to reduce a person’s incongruence?",
      "Moving the self-image and the ideal self closer together", ["Moving the self-image and the ideal self further apart from each other", "Describing themselves using more categories than before", "Forgetting that they have an ideal self and a self-image"],
      "Incongruence is a gap between self-image and ideal self, so anything that narrows the gap (for example, building skills or setting a more realistic ideal) makes the person more congruent."),
    M('Rogers: self-actualisation', "In Rogers’ theory, what is self-actualisation?",
      "Fulfilling your full potential, which is easier when you are congruent", ["Describing yourself using categories such as age", "Reaching a state of permanent incongruence in life", "Having enough food, water and shelter to live"],
      "For Rogers, self-actualisation is fulfilling your potential. It is easier to achieve when the self-image and ideal self match."),
    M('Key terms', "Which pair of terms and meanings is matched correctly?",
      "Self-image: how you see yourself; self-esteem: how much you value yourself", ["Self-image: how much you value yourself; self-esteem: how you see yourself", "Self-image: the person you want to be; self-esteem: your age and gender", "Self-image: awareness you exist; self-esteem: your ideal self"],
      "Self-image is the picture you hold of yourself. Self-esteem is the value you place on yourself. Students often swap these two."),
    M('Lewis: existential and categorical self', "A teacher listens to a three-year-old say, ‘I am a big sister, I have brown hair and I am four.’ What is the best explanation of this behaviour using Lewis (1990)?",
      "She is describing herself by categories, which shows the categorical self", ["She is showing congruence between her ideal self and her self-image", "She has not yet developed any sense of self at this age", "She is showing the existential self, awareness that she exists at all"],
      "Role (big sister), appearance (hair) and age are categories. Lewis called describing yourself this way the categorical self."),
    M('Congruence and incongruence', "Which statement about the ideal self is correct?",
      "It can differ from the self-image, and a big difference is linked to incongruence", ["It is always identical to the self-image in every person", "It only develops in infancy and then stops changing", "It is exactly the same thing as self-esteem for everyone"],
      "The ideal self is who you want to be. It may differ from the self-image; a large gap is incongruence."),
    M('Key terms', "Kit sees himself as good at music. He believes he is a talented guitarist and he is proud of this. Which two terms are shown?",
      "Self-image (good at music) and high self-esteem (proud)", ["Existential self (awareness) and incongruence (a mismatch)", "Ideal self (the person he wants to be) and categorical self", "Conditions of worth and self-actualisation (fulfilling potential)"],
      "Seeing himself as a talented guitarist is self-image. Feeling proud and valuing himself is high self-esteem.")
  ] };

  /* ---------- PSY-SLF-02 Rogers: positive regard ---------- */
  B['PSY-SLF-02'] = { title: 'Rogers: positive regard and conditions of worth', items: [
    M('Key terms', "In Rogers’ humanistic theory, what is ‘positive regard’?",
      "Love, warmth and acceptance from other people", ["The belief that you can do anything you set out to do", "A match between your self-image and your ideal self", "Praise that is given for passing an exam"],
      "Rogers said people need positive regard: love, warmth and acceptance from others, especially important figures like parents."),
    M('Key terms', "What is ‘unconditional positive regard’?",
      "Love and acceptance given whatever the person does or achieves", ["Love and approval given only when expectations are met", "Praise that is given for every single success the person has", "Acceptance that has to be earned through good behaviour at home"],
      "Unconditional positive regard has no strings attached. The person is accepted for who they are, whatever they achieve."),
    M('Key terms', "What is ‘conditional positive regard’?",
      "Approval and acceptance given only when the person meets others’ expectations", ["Love and acceptance given whatever the person does", "Acceptance that a child gives to their own parents each day", "A person’s own private opinion of themselves and their skills"],
      "Conditional positive regard depends on behaving or achieving in the way others want."),
    M('Key terms', "What are ‘conditions of worth’?",
      "Standards a person takes in from conditional regard and judges themselves by", ["The rewards a person gets for doing well at school or work", "The number of friends and supporters a person has in life", "The goals a person sets for the future of their own career"],
      "If love only comes when you meet certain standards, you take those standards in as conditions of worth and feel worthy only when you meet them."),
    M('Application: type of regard', "Mr Khan tells his son, ‘I will only be proud of you if you come top of the class.’ Which type of regard is this?",
      "Conditional positive regard", ["Unconditional positive regard", "Congruence", "Self-actualisation"],
      "Approval depends on meeting an expectation (coming top), so it is conditional."),
    M('Application: type of regard', "Whenever her daughter loses a match, Mrs Ali says, ‘I love you whether you win or lose.’ Which type of regard is she giving?",
      "Unconditional positive regard", ["Conditional positive regard given for winning", "Conditions of worth she has taken in", "Incongruence between her self-image and ideal self"],
      "Her love is not linked to winning, so it is unconditional."),
    M('Application: type of regard', "Which parent comment is an example of unconditional positive regard?",
      "‘I’m glad you tried your best, and I love you whatever the result.’", ["‘I’ll be very proud of you if you get an A in your test.’", "‘You can come out to play once your room is completely perfect.’", "‘I only like you when you do exactly what I tell you to.’"],
      "Unconditional regard does not depend on achievement or behaviour. The other comments attach conditions."),
    X('Application: type of regard', "Which of these comments show conditional positive regard?",
      ["‘I’ll only love you if you become a doctor.’", "‘You’re welcome in this house when you behave perfectly.’"], ["‘Whatever happens in your match, we love you.’", "‘We’re proud of you whether you win or lose.’"],
      "Conditional regard links love to meeting expectations. Statements that promise love whatever the outcome are unconditional."),
    M('Conditions of worth', "Gabi hides her love of painting from her family because they only praise her when she does sport. She now feels she is only worthwhile if she is sporty. Which Rogers concept does this show?",
      "Conditions of worth", ["Unconditional positive regard", "Congruence", "Self-actualisation"],
      "Gabi has taken in her family’s standard (be sporty) and judges her own worth by it. That is a condition of worth."),
    M('Conditions of worth', "How do conditions of worth develop, according to Rogers?",
      "A child takes in the standards linked to conditional regard and judges themselves by them", ["A child is given too much unconditional love by their parents", "A child compares their ideal self with their real ability at school", "A child reaches the top of a hierarchy of their basic needs"],
      "When regard is conditional, the child learns that being valued depends on meeting certain standards. These standards become conditions of worth."),
    M('Conditions of worth', "Arjun works long hours on homework because he believes, ‘I am only loved when I get top marks.’ Which Rogers idea best explains this?",
      "He has developed a condition of worth from conditional positive regard", ["He has been given unconditional positive regard by his parents", "His physiological needs for food and sleep are unmet at home", "He has reached self-actualisation and fully fulfilled his potential"],
      "His belief that love depends on top marks shows a condition of worth, which came from conditional regard."),
    M('Effects on self-esteem', "According to Rogers, what is a likely effect of growing up with mainly conditional positive regard?",
      "Lower self-esteem, anxiety and incongruence", ["Higher self-esteem and greater confidence in life", "A stronger existential self and sense of being separate", "Less need for approval and less fear of failing"],
      "A person who only feels valued when meeting conditions may feel worthless when they cannot, leading to low self-esteem, anxiety and incongruence."),
    M('Effects on self-esteem', "According to Rogers, what is a likely effect of growing up with unconditional positive regard?",
      "Higher self-esteem and confidence", ["Lower self-esteem and a lot more anxiety", "Stronger conditions of worth set by other people", "Greater incongruence between self-image and ideal self"],
      "Being accepted for who you are supports self-esteem and confidence, and makes it easier to try new things."),
    M('Effects on self-esteem', "Which is the best description of how conditional positive regard may affect self-esteem?",
      "Failing to meet others’ standards makes the person feel unworthy, lowering their self-esteem", ["Meeting every standard always makes the person feel worthless and sad all the time", "It has no link at all to how a person values themselves or their skills", "It raises self-esteem because the person is never criticised by anyone at all"],
      "A complete description links the type of regard (conditional) to the effect on self-esteem (lowered when standards are not met)."),
    M('Effects on self-esteem', "Why does unconditional positive regard help a child’s self-esteem?",
      "They feel valued for themselves without having to meet standards", ["They learn that love has to be earned by showing good behaviour", "They take in strict conditions of worth from their own parents", "They stop having an ideal self and a self-image as they grow"],
      "Being accepted whatever they do means a child does not need to earn love, so they can value themselves."),
    M('Application: counselling', "A counsellor listens to a client without judging and accepts whatever the client says. Which Rogers idea is the counsellor using?",
      "Unconditional positive regard", ["Conditions of worth that she has taken in", "Conditional positive regard from others", "Deficiency needs such as food and safety"],
      "Accepting the client without judgement gives them the unconditional positive regard they may have lacked, which can help rebuild self-esteem."),
    M('Application: type of regard', "Nadia’s parents praise her only when her test results are above 80%. She now believes her work is useless if it is below this. What has Nadia developed?",
      "A condition of worth", ["Unconditional positive regard", "An existential self", "Self-actualisation"],
      "Her worth is tied to a standard set by others (above 80%), so she has developed a condition of worth."),
    M('Neighbouring ideas', "Which pair of ideas comes from Rogers’ theory rather than from Maslow’s hierarchy?",
      "Conditions of worth and unconditional positive regard", ["Safety needs and esteem needs", "Deficiency needs and growth needs", "Physiological needs and self-actualisation as the top level"],
      "Conditions of worth and positive regard belong to Rogers. Safety, esteem and deficiency needs belong to Maslow."),
    M('Neighbouring ideas', "Who developed the humanistic ideas of positive regard and conditions of worth?",
      "Rogers", ["Maslow", "Allport", "Cattell"],
      "Positive regard and conditions of worth are Rogers’ ideas (1951/1959). Maslow wrote about the hierarchy of needs."),
    M('Evaluation', "Which is a strength of Rogers’ ideas about positive regard?",
      "They are useful in counselling and parenting", ["They have been tested using exact scientific measurements", "They explain physical needs such as hunger", "They show that praise is always harmful"],
      "A strength is practical value: counsellors and parents can use unconditional positive regard to support self-esteem."),
    M('Evaluation', "Which is a weakness of Rogers’ ideas about positive regard and conditions of worth?",
      "The ideas are hard to measure scientifically", ["They give no practical ideas for helping people in need", "They were only ever tested on laboratory animals", "They cannot be applied to parenting or to counselling at all"],
      "Concepts like conditions of worth and unconditional regard are abstract and hard to measure, which makes the theory hard to test."),
    M('Application: type of regard', "A father says ‘Well done for the A grade, I’m so proud of you’ but is silent and cold when his daughter gets a B. What does this show?",
      "Praise given only for success is conditional positive regard", ["All praise is a kind of unconditional positive regard for the child", "The daughter has reached self-actualisation already at a young age", "Her father is giving her unconditional love and acceptance of who she is"],
      "The father’s approval depends on the grade, so it is conditional. Not all praise is unconditional."),
    M('Effects on self-esteem', "Mr Osei tells his son that he is loved just as he is, even after the boy fails a swimming test. How is this likely to affect him, according to Rogers?",
      "He is likely to have higher self-esteem and the confidence to try new things", ["He is likely to develop very strong conditions of worth about success", "He is likely to feel anxious about failing in the future at tests", "He is likely to become incongruent and low in his confidence in school"],
      "This is unconditional positive regard. He does not have to earn love, which supports self-esteem and confidence.")
  ] };

  /* ---------- PSY-SLF-07 Measuring personality ---------- */
  B['PSY-SLF-07'] = { title: 'Measuring personality: traits, scales and the 16PF', items: [
    M('Scales and types', "What is a personality scale?",
      "A measure that places people at a point on a continuum for each trait", ["A measure that sorts people into separate categories or groups", "A test of how fast a person learns new things at school", "A list of a person’s favourite activities and hobbies at home"],
      "Personality scales give a score along a continuum (for example, from reserved to warm). Placing people into categories is the personality types approach."),
    M('Scales and types', "What is meant by measuring personality using ‘types’?",
      "Placing people into categories", ["Giving people a score on a continuum for each trait", "Measuring the size of different brain areas", "Counting the number of friends a person has"],
      "Types put people into categories. Scales give scores on a continuum."),
    M('Scales and types', "A questionnaire gives Jordan a score from 1 to 10 for how sociable he is. Which approach to measuring personality is this?",
      "A personality scale", ["A personality type", "A cardinal trait", "A factor analysis"],
      "A score along a continuum is a scale. A type would simply label Jordan as one category."),
    M('Scales and types', "Which is a way that personality can be measured?",
      "Asking a person to complete a questionnaire of trait statements", ["Timing how fast a person can run 100 metres on a track", "Measuring a person’s height and weight at a doctor’s clinic", "Counting how many hours a person sleeps each night at home"],
      "Most measures of personality are self-report questionnaires in which people rate how well trait statements describe them."),
    M('Allport’s traits', "According to Allport (1936), what is a cardinal trait?",
      "A trait that dominates a person’s whole life and is rare", ["A main characteristic that describes a person in most situations", "A trait that only appears in some situations", "One of 16 factors found by factor analysis"],
      "Cardinal traits dominate everything a person does and are rare. Central traits are the main characteristics, and secondary traits only appear in some situations."),
    M('Allport’s traits', "According to Allport (1936), what is a secondary trait?",
      "A trait that only appears in some situations", ["A trait that dominates a person’s whole life", "One of the 5–10 main characteristics of a person", "A trait that cannot be measured"],
      "Secondary traits show up only in particular situations, for example getting anxious only when speaking in public."),
    M('Allport’s traits', "Leah’s friends describe her as honest, creative, funny, reliable and shy. According to Allport, which level of trait are these descriptions?",
      "Central traits", ["Cardinal traits", "Secondary traits", "Personality types"],
      "Central traits are the main characteristics that describe a person (around 5 to 10 of them), so these descriptions are central traits."),
    M('Allport’s traits', "Dmitri’s whole life revolves around beating a world record. Everything he does, from his diet to his friends, is shaped by this one drive. Which level of trait fits best?",
      "A cardinal trait", ["A central trait", "A secondary trait", "A personality scale"],
      "A single trait that dominates a person’s whole life is a cardinal trait, and these are rare."),
    M('Allport’s traits', "Tom is calm and confident at work and with friends, but becomes anxious only when he has to speak in public. According to Allport, his anxiety is a…",
      "secondary trait", ["cardinal trait", "central trait", "personality type"],
      "It appears only in one situation (public speaking), so it is a secondary trait."),
    M('Allport’s traits', "Roughly how many central traits did Allport think describe a person?",
      "Around 5–10", ["Exactly 1", "Exactly 16", "Over 100"],
      "Allport said a person has only a few cardinal traits (if any) and around 5–10 central traits. The figure 16 relates to Cattell."),
    M('Allport’s traits', "Which psychologist described traits at three levels: cardinal, central and secondary?",
      "Allport", ["Cattell", "Maslow", "Rogers"],
      "Allport (1936) described these three levels of trait. Cattell is associated with the 16PF."),
    M('Cattell and the 16PF', "What did Cattell (1946) do to arrive at the 16 personality factors?",
      "Used factor analysis to reduce many trait words to 16 factors", ["Placed people into 16 different personality types", "Observed 16 people over many years in their homes", "Asked people to rank 16 different jobs in order of status"],
      "Cattell used factor analysis to reduce a large number of personality words to 16 underlying factors, which the 16PF questionnaire measures."),
    M('Cattell and the 16PF', "Which statement about the 16PF is correct?",
      "Each factor is a scale between two extremes, such as reserved to warm", ["It sorts people into 16 separate personality types", "Each factor is either fully present or fully absent", "It measures only three traits that dominate a life"],
      "The 16PF measures 16 factors, each as a scale. It does not produce 16 types."),
    M('Cattell and the 16PF', "A 16PF factor runs from ‘reserved’ (1) to ‘warm’ (10). Anil scores 9. What does this suggest about Anil?",
      "He is towards the warm end of the scale", ["He is towards the reserved end of the scale", "He is a ‘warm type’ and cannot be reserved", "He has a cardinal trait"],
      "On a scale from reserved (1) to warm (10), a score of 9 is close to the warm extreme."),
    M('Cattell and the 16PF', "Ian has completed the 16PF. His results show a low score on ‘tension’, where the two ends of the scale are ‘relaxed’ and ‘tense’. What does a low score mean?",
      "He is towards the relaxed end of the scale", ["He is towards the tense end of the scale", "He is a ‘relaxed type’ and cannot feel tension", "He has no tension factor"],
      "A low tension score means he is near the ‘relaxed’ end of that factor’s scale."),
    M('Cattell and the 16PF', "A manager gives all job applicants the same 16PF questionnaire so they can be compared. Which is the best reason this is a strength?",
      "It is standardised, so everyone answers the same questions in the same way", ["It cannot be faked by the applicants who complete it", "It measures only one trait in each of its applicants", "It uses objective brain scans of every single applicant"],
      "Standardised procedures mean scores are comparable between people. The 16PF is self-report, so it can be faked."),
    X('Cattell and the 16PF', "Which of these statements about Cattell’s 16PF are correct?",
      ["It was developed using factor analysis", "It is usually completed as a self-report questionnaire", "Each factor is a scale between two extremes"], ["It places each person into one of 16 types", "It describes cardinal, central and secondary traits"],
      "The 16PF uses factor analysis, is a self-report questionnaire and measures scales. It does not produce types, and the three trait levels are Allport’s."),
    X('Allport’s traits', "Which of these statements about Allport’s trait levels are correct?",
      ["Cardinal traits are rare", "Secondary traits appear only in some situations"], ["Central traits dominate a person’s whole life", "There are exactly 16 trait levels", "Allport used factor analysis to find the traits"],
      "Cardinal traits are rare, secondary traits are situational, and central traits are the main characteristics. Factor analysis and the number 16 belong to Cattell."),
    M('Evaluation of personality measures', "Sven answers ‘I never get cross’ on a questionnaire because he wants to look good, though he often does. Which problem does this show?",
      "Social desirability, which distorts the personality score", ["Factor analysis, which reduces the long trait list", "A cardinal trait, which dominates the whole of his life", "A personality type, which sorts him into a single category"],
      "People may answer to appear in a favourable way. This social desirability bias makes the score a less accurate measure of true personality."),
    M('Evaluation of personality measures', "Which is a weakness of using self-report questionnaires to measure personality?",
      "People may lie or answer in a socially desirable way", ["They are always unstandardised and different each time", "They cannot give any numerical scores to compare people", "They can only ever measure one trait at a time in a person"],
      "Because people report on themselves, they may exaggerate or give the answers they think look best, reducing accuracy."),
    M('Evaluation of personality measures', "Which is a weakness of measuring personality traits?",
      "A person’s behaviour may change with the situation, so a trait score may not predict all behaviour", ["Traits can never be given a score by any questionnaire", "Traits are the same for absolutely everyone in the world", "A trait score can only be found by observing animals in labs"],
      "Behaviour can vary across situations, so a single trait score may not predict how a person acts everywhere."),
    M('Neighbouring ideas', "Which pair correctly matches the psychologist to their contribution to personality measurement?",
      "Cattell: 16 factors from factor analysis; Allport: cardinal, central and secondary traits", ["Cattell: cardinal, central and secondary traits; Allport: 16 factors", "Allport: the 16PF questionnaire; Cattell: the hierarchy of needs", "Cattell: conditions of worth and regard; Allport: factor analysis"],
      "Cattell (1946) used factor analysis and the 16PF. Allport (1936) described three levels of trait. Many students swap them."),
    M('Application', "Carys tells Dana that her ‘organised’ score on a questionnaire shows how much of that trait she has, on a line from low to high. Which approach is Carys describing?",
      "A personality scale", ["A personality type", "A cardinal trait", "A condition of worth"],
      "Placing someone at a point on a continuum from low to high is a scale.")
  ] };

  /* ---------- PSY-SLF-08 Van Houtte and Jarvis (1995) ---------- */
  B['PSY-SLF-08'] = { title: 'Van Houtte & Jarvis (1995): pets and children', items: [
    M('Aim and sample', "What was the aim of Van Houtte and Jarvis (1995)?",
      "To find out whether owning a pet helps children’s psychological development", ["To find out whether children prefer cats or dogs as their favourite pets", "To test whether pets reduce children’s physical illness over a long period of time", "To compare the self-esteem of boys and girls across several different grades"],
      "The study investigated whether having a pet is linked to children’s psychological development, such as self-esteem and autonomy."),
    M('Aim and sample', "How many children took part in Van Houtte and Jarvis (1995)?",
      "130", ["103", "150", "310"],
      "The sample was 130 children from the USA."),
    M('Aim and sample', "Which description of the sample in Van Houtte and Jarvis (1995) is correct?",
      "Children in grades 3–4, 5–6 and 7–8 in the USA", ["Adults who owned a cat or dog in the UK and who lived alone", "Children aged 2–4 in nursery schools in several European countries", "Only 10-year-old girls in the USA who lived in one city"],
      "The 130 children came from the USA and were in grades 3–4, 5–6 and 7–8, so a range of ages."),
    M('Procedure', "Which animals counted as pets for pet owners in Van Houtte and Jarvis (1995)?",
      "Only cats and dogs", ["Any animal the child cared for, including fish", "Only dogs", "Only animals kept outside the home"],
      "The study only counted children with a cat or dog as pet owners, a fairly narrow definition of a pet."),
    X('Procedure', "Which of these were measured using questionnaires in Van Houtte and Jarvis (1995)?",
      ["Self-esteem", "Autonomy", "Life satisfaction"], ["Intelligence quotient", "Reading ability"],
      "Children completed questionnaires on self-esteem, autonomy, self-concept and life satisfaction. IQ and reading ability were not measured."),
    M('Procedure', "How were the pet owners and non-owners in Van Houtte and Jarvis (1995) compared?",
      "Matched on factors such as family background, then compared on questionnaire scores", ["Randomly assigned pets by the researchers, then compared on their questionnaire scores", "Observed at home for a year, then compared on their daily behaviour", "Interviewed once each, with no scores recorded and compared by the researchers"],
      "The researchers compared existing pet owners with non-owners who were matched on factors such as family background. They did not give children pets."),
    M('Findings', "On which measure did pet owners score higher than non-owners in Van Houtte and Jarvis (1995)?",
      "Autonomy", ["Intelligence", "School grades", "Number of friends"],
      "Pet owners scored higher on autonomy, the ability to act independently."),
    M('Findings', "Which group of children showed higher self-esteem if they owned a pet in Van Houtte and Jarvis (1995)?",
      "Fifth- and sixth-graders", ["Third- and fourth-graders only", "Seventh- and eighth-graders only", "All age groups"],
      "Pet owners reported better self-esteem among the fifth- and sixth-graders. Claiming all age groups is a common mistake."),
    M('Findings', "Which statement about the findings of Van Houtte and Jarvis (1995) is NOT correct?",
      "Pet owners in every age group had higher self-esteem", ["Pet owners scored higher on autonomy", "Fifth- and sixth-grade owners reported better self-esteem", "The benefits seemed linked to having a pet, not how attached the child was"],
      "The self-esteem difference was found in fifth- and sixth-graders, not in every age group."),
    M('Findings', "What did Van Houtte and Jarvis (1995) find about how attached children were to their pets?",
      "The benefits seemed to come from having a pet rather than how attached the child was", ["Only children very attached to their pet showed benefits in their autonomy scores", "Attachment to the pet had the largest effect of all on every measure used", "Children who were not attached to the pet showed lower autonomy than the children without pets"],
      "The researchers concluded that the benefits seemed to come from having a pet, not from how strongly the child was attached."),
    M('Conclusions', "Which conclusion is best supported by Van Houtte and Jarvis (1995)?",
      "Having a pet may help children’s development, for example their autonomy", ["Owning a pet is guaranteed to raise self-esteem in every child of every age in the study", "Children without pets will never develop autonomy as they grow older", "Pets are more useful for development than friends or family are for children"],
      "The results suggest a link between owning a pet and development, but they cannot prove cause, so cautious wording is needed."),
    M('Conclusions', "A headteacher says, ‘Van Houtte and Jarvis proved that pets cause higher self-esteem.’ What is the best response?",
      "The study compared existing owners and non-owners, so it cannot prove pets caused the difference", ["That is right because the sample had 130 children from different grades", "That is right because the questionnaires were standardised for every child in the study", "That is wrong because pets reduce self-esteem in children of every age"],
      "Comparing pet owners with non-owners shows a link, not a cause. Other differences between the groups could explain the results."),
    M('Evaluation', "Which is a weakness of the data collected in Van Houtte and Jarvis (1995)?",
      "It was self-report, so children may not have answered truthfully", ["It was collected only from adults who had owned pets all their lives", "It used observations by strangers who did not know the children", "It was based on one child who was studied for many years"],
      "Children completed questionnaires about themselves, and self-report data can be affected by exaggeration or wanting to look good."),
    M('Evaluation', "Why is a narrow definition of a pet (only cats and dogs) a limitation of Van Houtte and Jarvis (1995)?",
      "The findings may not apply to children who keep other animals", ["It means the sample was too large for the researchers to analyse", "It makes the data qualitative rather than quantitative in nature", "It means the study was unethical because animals were harmed"],
      "Only cats and dogs counted, so we cannot say the same results would be found for children with other types of pet."),
    M('Evaluation', "Matching pet owners and non-owners on factors such as family background was a strength of the study because it…",
      "reduced the chance that other differences caused the results", ["proved that pets cause higher autonomy in all of the children", "removed the need for questionnaires in the study entirely", "made the sample larger than it would have been"],
      "Matching helps control extraneous variables such as family background. It still cannot prove cause."),
    M('Evaluation', "The children in Van Houtte and Jarvis (1995) were all from the USA. Which limitation does this create?",
      "The results may not generalise to children in other countries", ["The questionnaires were too long for the children to complete", "The study had no comparison group of children without pets", "The sample was too small to find any difference between the two groups"],
      "A sample from one country may not represent children in other cultures, so generalising is difficult."),
    M('Application', "Nia is a 10-year-old in the fifth grade and has a pet dog. Based on Van Houtte and Jarvis (1995), what might a researcher expect compared with a matched non-owner?",
      "Higher autonomy and better self-esteem", ["Lower autonomy and better self-esteem", "Lower self-esteem but higher life satisfaction", "No difference on any measure"],
      "The study found higher autonomy in pet owners and better self-esteem among fifth- and sixth-graders, so both are predicted for Nia."),
    M('Application', "A primary school considers letting pupils look after a class rabbit to help their independence. Which finding from Van Houtte and Jarvis (1995) most supports this idea?",
      "Pet owners scored higher on autonomy", ["Pet owners had lower life satisfaction", "Attachment mattered more than ownership", "Only cat owners were affected"],
      "Autonomy is independence, and the study found owners scored higher on it. Note, though, that the study only counted cats and dogs."),
    M('Application', "Ellis has a goldfish and Pru has a pet dog. Under the definition of pet owner used by Van Houtte and Jarvis (1995), which child would be counted as a pet owner?",
      "Pru only", ["Ellis only", "Both Ellis and Pru", "Neither Ellis nor Pru"],
      "Only children with a cat or dog counted as pet owners in the study, so Pru would be counted and Ellis would not."),
    M('Application', "Tariq has a dog but is less independent than his classmate Joe, who has no pet. Tariq says, ‘This proves the study is wrong.’ What is the best reply?",
      "The study found average differences between groups, so individual children can differ", ["He is right, because one exception disproves the whole study and all its results", "He is wrong, because every pet owner has higher autonomy than every non-owner", "He is right, because the study only included classmates from the same school"],
      "The findings describe differences between groups of owners and non-owners on average. One child who does not fit the pattern does not make the results wrong."),
    M('Method and ethics', "Why would researchers running a study like Van Houtte and Jarvis (1995) need permission from parents or guardians?",
      "The participants were children, who cannot give fully informed consent alone", ["Because the questionnaires were secret from everybody except the child", "Because the pets were dangerous to the children and to staff", "Because the children were adults when they took part in the study"],
      "When participants are children, researchers normally obtain consent from parents or guardians, an ethical requirement."),
    M('Method and ethics', "Which description of the method of Van Houtte and Jarvis (1995) is most accurate?",
      "A comparison of pet owners and non-owners using questionnaires", ["A laboratory experiment in which children were given pets to look after", "A case study of one family with a pet over many years", "An observation of children in a playground with and without pets"],
      "Existing pet owners and non-owners completed questionnaires. The researchers did not manipulate pet ownership."),
    M('Method and ethics', "Why can the study not show that owning a pet causes higher autonomy?",
      "Pet ownership was not controlled by the researchers, so other factors may explain the difference", ["Because the sample was only one child taken from a single school", "Because questionnaires cannot measure autonomy in any child at all", "Because the study had no non-owners to compare the owners with"],
      "The researchers did not allocate pets to children, so factors other than pets may differ between the groups.")
  ] };

  /* ---------- PSY-SLF-05 Free will ---------- */
  B['PSY-SLF-05'] = { title: 'Free will: Baumeister and Vohs & Schooler', items: [
    M('Key terms', "What is meant by ‘free will’ in psychology?",
      "The view that people actively choose their own behaviour", ["The view that behaviour is caused by forces we cannot control", "The freedom to do absolutely anything without consequences", "The view that all behaviour is learned from parents"],
      "Free will means people choose how they behave. It does not mean doing whatever you like without limits."),
    M('Key terms', "What is meant by ‘determinism’?",
      "The view that behaviour is caused by forces outside our control", ["The view that people freely choose their behaviour without any outside causes", "The ability to resist impulses and make careful choices", "The belief that people are born good and stay good all their lives"],
      "Determinism says behaviour is the result of causes such as genes and experiences that we cannot control."),
    M('Key terms', "Which scenario best describes a belief in determinism?",
      "‘My choices were all set by my genes and upbringing; I couldn’t have done anything else.’", ["‘I chose to study because I decided it was best for my future.’", "‘I can resist any temptation, provided that I decide to do so.’", "‘I am fully responsible for every decision that I make in life.’"],
      "Seeing behaviour as fixed by causes outside our control is determinism. The other statements show belief in free will."),
    M('Key terms', "Which of these is NOT an accurate meaning of free will in the theory of Baumeister?",
      "Doing anything you want without thinking about others", ["An advanced form of self-control that helps us act well", "A way of making rational choices about how to behave", "A way of resisting selfish impulses so we help other people"],
      "For Baumeister, free will is an advanced form of self-control and rational choice. It does not mean behaving without regard for others."),
    M('Baumeister (2008)', "According to Baumeister (2008), what is the role of free will?",
      "It helps people use self-control to behave well", ["It makes people act on every impulse they feel at any moment", "It forces people to be aggressive towards others around them", "It stops people from learning from their mistakes in life"],
      "Baumeister saw free will as a form of self-control and rational choice that helps people resist selfish impulses and behave in socially desirable ways."),
    M('Baumeister (2008)', "What did Baumeister (2008) argue could happen if people stop believing in free will?",
      "They may behave in more antisocial ways, such as helping less", ["They will become more helpful to others in their daily lives", "They will become better at self-control over their own impulses", "Their behaviour will not change at all in any situation"],
      "Baumeister argued that if people do not believe their choices matter, they may be less likely to resist selfish impulses, leading to antisocial behaviour such as aggression or less helping."),
    M('Baumeister (2008)', "Cora reads an article claiming all behaviour is predetermined. Later she does not bother to help a classmate who has dropped her books. Which explanation uses Baumeister’s theory?",
      "Weaker belief in free will can reduce helping and other kind behaviour", ["Strong belief in free will makes people less helpful towards other people", "Reading articles always increases helping in everyone who reads them", "Free will has no effect on how people behave towards others in any situation"],
      "Baumeister said that not believing in free will can lead to less helping and more antisocial behaviour. Cora’s behaviour fits this."),
    M('Vohs and Schooler (2008)', "What did Vohs and Schooler (2008) set out to investigate?",
      "To test whether weakening belief in free will makes people cheat more", ["To test whether people with strong free will are more intelligent than other people", "To find out how many people cheat in exams in a typical university", "To test whether determinism is true for all human behaviour"],
      "The researchers wanted to see whether encouraging a belief that free will is an illusion makes people more likely to cheat."),
    M('Vohs and Schooler (2008)', "How did Vohs and Schooler (2008) change participants’ belief in free will?",
      "They read a passage saying free will is an illusion, or a neutral one", ["Participants were hypnotised to change their views about free will", "Participants were shown pictures of people cheating in different situations", "Participants were given questionnaires about their parents and their childhood"],
      "One group read a passage arguing that free will is an illusion; the other read a neutral passage. The groups were then compared."),
    M('Vohs and Schooler (2008)', "In Vohs and Schooler (2008), how was cheating measured?",
      "Participants had the chance to cheat while doing maths problems", ["Participants were asked if they had ever cheated before in their lives", "Participants’ teachers reported their cheating after the study ended", "Participants copied a poem from the board as quickly as they could"],
      "After reading their passage, participants did maths problems where they had an opportunity to cheat."),
    M('Vohs and Schooler (2008)', "What was the main result of Vohs and Schooler (2008)?",
      "Those who read the determinism passage cheated more", ["Those who read the determinism passage cheated less", "Both passages led to the same level of cheating", "Only people with weak free-will scores took part"],
      "Weakening belief in free will increased cheating. Reversing this result is a common error."),
    M('Vohs and Schooler (2008)', "What did Vohs and Schooler (2008) find about participants’ scores on a free-will belief measure?",
      "Lower free-will scores were linked to more cheating", ["Higher free-will scores were linked to more cheating", "Free-will scores had no relationship to cheating", "Free-will scores were the same for all participants"],
      "There was a correlation: the lower a participant’s belief in free will, the more they cheated."),
    X('Vohs and Schooler (2008)', "Which of these statements about Vohs and Schooler (2008) are correct?",
      ["Some participants read a neutral passage", "Participants had the opportunity to cheat on maths problems"], ["The determinism group cheated less than the neutral group", "The participants were children", "The study took place in a real classroom"],
      "A neutral passage group was used for comparison, and cheating was possible on maths problems. The determinism group cheated more, and the task was set up in a laboratory."),
    M('Vohs and Schooler (2008)', "What was the purpose of the neutral passage in Vohs and Schooler (2008)?",
      "It gave a group whose belief in free will was left alone", ["It trained participants to cheat on the maths problems", "It made sure all participants cheated equally on the maths task", "It tested participants’ memory for the passage they read"],
      "Without a neutral comparison, the researchers could not tell whether reading the determinism passage changed cheating."),
    M('Vohs and Schooler (2008)', "Which conclusion is best supported by Vohs and Schooler (2008)?",
      "Weakening belief in free will increases cheating", ["Weakening belief in free will decreases cheating", "Weakening belief in free will has no effect on cheating", "Cheating is always caused by determinism"],
      "The determinism passage led to more cheating, so reducing belief in free will increased cheating."),
    M('Application', "A teacher tells her class, ‘You can’t help being lazy; it’s just how your brain is wired.’ Her students then copy more homework. Which study from this topic does this behaviour support?",
      "Vohs and Schooler (2008), because a weaker belief in free will increased cheating", ["Baumeister (2008), because determinism improves self-control", "Vohs and Schooler (2008), because a stronger belief in free will increased cheating", "Neither study, because beliefs never affect behaviour"],
      "The teacher weakened her students’ belief in free will, and they cheated more, which matches Vohs and Schooler’s result."),
    M('Application', "A school plans to reduce cheating by teaching students that they choose their own actions and are responsible for them. Which idea supports this plan?",
      "Stronger belief in free will is linked to less cheating", ["Stronger belief in determinism is linked to less cheating", "Belief in free will is unrelated to behaviour", "Cheating can only be reduced by punishments"],
      "In Vohs and Schooler’s study, weaker free-will belief was linked to more cheating, so promoting belief in free will might help."),
    M('Application', "Anil is told his behaviour is controlled by his genes, and he decides to take a bigger share of the group’s sweets. Using Baumeister’s theory, what is the best explanation?",
      "He may find it harder to resist selfish impulses", ["Belief in free will made him selfish in the sweet-sharing task of the day", "Genes cause people to be generous whatever they believe about choice", "Self-control is not needed to share things with other people at all"],
      "Baumeister said free will is a form of self-control that helps people resist selfish impulses. If belief in it is weakened, selfish behaviour may increase."),
    M('Evaluation', "Which is a weakness of the Vohs and Schooler (2008) study?",
      "Lab cheating may not match real-life cheating", ["It had no comparison group to show the effect of the passage read", "It could not be repeated because the task was far too complex", "It did not measure cheating in any of its participants at all"],
      "Laboratory tasks lack real-life validity: cheating on a short task for little reward may differ from real cheating."),
    M('Evaluation', "Why might it be difficult to generalise the results of Vohs and Schooler (2008)?",
      "The participants were students, who may not represent other groups", ["Because the study was a case study of one person only", "Because the participants were all children from the same school year", "Because the results were not significant at any level of confidence"],
      "The sample was students, so the findings may not apply to other ages or backgrounds."),
    M('Evaluation', "How does Vohs and Schooler (2008) relate to Baumeister’s (2008) theory?",
      "It supports Baumeister’s idea that weaker free-will belief worsens behaviour", ["It contradicts Baumeister’s theory about free will and self-control", "It is unrelated to Baumeister’s theory of free will and behaviour", "It shows that determinism improves behaviour in the long term"],
      "Cheating is antisocial behaviour, and it increased when belief in free will was weakened, as Baumeister predicted."),
    M('Evaluation', "Which is a strength of using a neutral passage in the experiment by Vohs and Schooler (2008)?",
      "It gives a comparison for the determinism passage", ["It shows that all participants cheated on the maths problems given", "It stops participants noticing the maths task until they start it", "It proves free will exists in every human being on the planet"],
      "Comparing the two passage groups lets researchers see whether the determinism passage specifically changed cheating."),
    M('Evaluation', "Which of these is an evaluation point, rather than a description, of the study by Vohs and Schooler (2008)?",
      "The artificial setting may reduce real-life validity", ["Participants read one of two passages before the maths task began", "Participants did maths problems with a chance to cheat on them", "The determinism group cheated more than the neutral group did"],
      "An evaluation point makes a judgement about the quality or usefulness of the study. The other options simply describe the procedure or results.")
  ] };

  /* ---------- PSY-PER-01 Monocular depth cues ---------- */
  var SV1 = '<svg viewBox="0 0 240 140" role="img" aria-label="Two straight lines drawn from the bottom edge of the picture that move closer together and meet at a point on the horizon line">' +
    '<rect x="0" y="0" width="240" height="140" fill="#ffffff" stroke="#9aa5b8"/><line x1="0" y1="60" x2="240" y2="60" stroke="#9aa5b8"/>' +
    '<line x1="60" y1="140" x2="120" y2="60" stroke="#303a4c" stroke-width="3"/><line x1="180" y1="140" x2="120" y2="60" stroke="#303a4c" stroke-width="3"/></svg>';
  var SV2 = '<svg viewBox="0 0 240 140" role="img" aria-label="A blue rectangle partly hides a red rectangle that sits behind it">' +
    '<rect x="0" y="0" width="240" height="140" fill="#ffffff" stroke="#9aa5b8"/><rect x="95" y="35" width="90" height="70" fill="#e4464f"/><rect x="50" y="55" width="90" height="70" fill="#195d9b"/></svg>';
  var SV3 = '<svg viewBox="0 0 240 140" role="img" aria-label="Two identical circles of the same size on a plain background: one high up near a horizon line and one low down near the bottom of the picture">' +
    '<rect x="0" y="0" width="240" height="140" fill="#ffffff" stroke="#9aa5b8"/><line x1="0" y1="40" x2="240" y2="40" stroke="#9aa5b8"/><circle cx="70" cy="55" r="14" fill="#195d9b"/><circle cx="170" cy="115" r="14" fill="#195d9b"/></svg>';
  B['PSY-PER-01'] = { title: 'Monocular depth cues: judging distance with one eye', items: [
    M('Defining the cues', "What is meant by ‘superimposition’ as a depth cue?",
      "An object that is partly hidden by another is judged to be further away", ["An object that looks smaller is judged to be further away from the viewer", "Parallel lines appear to meet at a point in the distance on the horizon line", "Distant surfaces look finer and smoother than near ones in a scene"],
      "With superimposition (overlap), the object that is blocked from view is seen as the more distant one."),
    M('Defining the cues', "What is meant by ‘relative size’ as a depth cue?",
      "Of two similar objects, the smaller-looking one is judged to be further away", ["The object that is partly hidden is judged to be further away than the other one", "Objects near the horizon are judged to be further away than objects lower down", "A familiar object keeps its size however far away it is from the observer"],
      "Relative size compares two objects of the same kind: the one casting a smaller image seems more distant."),
    M('Defining the cues', "What is meant by ‘linear perspective’ as a depth cue?",
      "Parallel lines appear to meet at a vanishing point on the horizon", ["Distant objects look finer and blurrier than near objects", "Overlapping objects show which is closer to the viewer", "Objects higher in a scene look closer than objects lower down"],
      "Linear perspective: lines such as roads and rails seem to converge towards the horizon, signalling distance."),
    M('Defining the cues', "What is meant by ‘texture gradient’ as a depth cue?",
      "Nearby surfaces show coarse, clear detail while distant ones look finer and smoother", ["Parallel lines appear to meet in the distance at the horizon", "Nearby objects are partly hiding distant ones from the viewer", "Objects lower down appear to be further away than objects higher up"],
      "Texture gradient: detail such as grass or paving is coarse close to us and becomes finer and blurrier with distance."),
    M('Defining the cues', "What is meant by ‘height in the plane’ as a depth cue?",
      "Objects nearer the horizon line look further away than objects lower in the scene", ["Taller objects are always judged to be nearer than shorter objects", "Objects higher in the sky are judged to be nearer than objects on the ground", "The tallest object in a scene appears largest whatever its distance"],
      "In a scene, objects placed closer to the horizon look more distant than those lower down the picture."),
    M('Identifying cues', "Rani looks along a railway line and sees the two rails seem to come together in the distance. Which cue is she using to judge how far the track goes?",
      "Linear perspective", ["Texture gradient", "Superimposition", "Relative size"],
      "Parallel lines that appear to converge towards a point on the horizon show linear perspective."),
    M('Identifying cues', "On a beach, Cal can see each pebble clearly near his feet but the pebbles far away blur into a smooth grey surface. Which cue tells him which area is further away?",
      "Texture gradient", ["Linear perspective", "Height in the plane", "Superimposition"],
      "Detail becomes finer and smoother with distance. This is texture gradient."),
    M('Identifying cues', "Two lamp posts are identical in real life, but one looks much smaller in Lena’s view down the street. She judges that it is further away. Which cue is she using?",
      "Relative size", ["Size constancy", "Texture gradient", "Linear perspective"],
      "Of two similar objects, the one that looks smaller is judged to be more distant. This is relative size."),
    M('Identifying cues', "A tree trunk partly blocks Jin’s view of a barn. He decides that the barn is behind the tree. Which cue is he using?",
      "Superimposition", ["Relative size", "Texture gradient", "Height in the plane"],
      "When one object overlaps and hides part of another, the hidden one is judged to be further away."),
    M('Identifying cues', "In a drawing, a man and a woman are the same size, but the woman is drawn nearer the horizon line. People say she looks further away. Which cue is working here?",
      "Height in the plane", ["Linear perspective", "Superimposition", "Stereopsis"],
      "Objects drawn nearer the horizon appear to be more distant. Here size is equal, so the cue is height in the plane."),
    M('Binocular and monocular', "Which of these is NOT a monocular depth cue?",
      "Stereopsis", ["Superimposition", "Relative size", "Texture gradient"],
      "Stereopsis uses the slightly different images from the two eyes, so it is a binocular cue. The others work with one eye."),
    X('Binocular and monocular', "Which of these are monocular depth cues?",
      ["Linear perspective", "Superimposition", "Height in the plane"], ["Stereopsis", "Ambiguous figure"],
      "Monocular cues work with one eye. Stereopsis needs two eyes, and an ambiguous figure is a type of visual illusion rather than a depth cue."),
    M('Binocular and monocular', "Why can a person with sight in only one eye still judge distance quite well?",
      "Monocular cues need only one eye", ["Binocular cues work with one eye", "Stereopsis does not depend on both eyes", "The brain does not need depth cues"],
      "Cues such as relative size, texture gradient and linear perspective are monocular, so one eye is enough to use them."),
    X('Cues in art', "A painter wants a flat canvas to look deep. Which of these techniques show depth using monocular cues?",
      ["Drawing distant trees smaller than near ones", "Overlapping a hill behind a farm building", "Drawing roads that narrow towards a point on the horizon"], ["Drawing distant objects larger than near ones", "Making near surfaces smoother and blurrier than far ones"],
      "Relative size, superimposition and linear perspective all give depth. Distant objects should look smaller, and distant surfaces (not near ones) should look smoother."),
    M('Cues in art', "Why do artists use depth cues in paintings?",
      "To make a flat picture look three-dimensional", ["To make the picture look flat and two-dimensional", "To show how each eye sees differently in real life", "To make viewers use stereopsis when they look at it"],
      "A canvas is flat, so artists use cues such as linear perspective and relative size to create a sense of depth."),
    M('Relative size and constancy', "Which statement correctly separates relative size from size constancy?",
      "Relative size is a depth cue; size constancy keeps an object looking the same size", ["Relative size means objects shrink as they move away; constancy means they grow bigger", "Relative size is a binocular cue; size constancy is a monocular cue", "They are the same idea, and the two names can be swapped freely"],
      "Relative size is a depth cue about distance. Size constancy is about seeing an object as the same size even when its image changes."),
    M('Identifying cues', "Look at the figure. Which monocular depth cue does it show?",
      "Linear perspective", ["Superimposition", "Relative size", "Height in the plane"],
      "The two lines converge towards a point on the horizon, which is linear perspective.", { svg: SV1, family: 'per01-fig1' }),
    M('Identifying cues', "Which monocular cue tells the viewer which shape is further away in this figure?",
      "Superimposition", ["Texture gradient", "Linear perspective", "Stereopsis"],
      "The blue shape overlaps and hides part of the red shape, so the red shape is judged to be behind. This is superimposition.", { svg: SV2, family: 'per01-fig2' }),
    M('Identifying cues', "The two circles in the figure are exactly the same size. Which cue makes one look further away than the other?",
      "Height in the plane", ["Relative size", "Superimposition", "Texture gradient"],
      "The circle nearer the horizon line seems more distant, even though the sizes are the same. The cue is height in the plane.", { svg: SV3, family: 'per01-fig3' }),
    M('Identifying cues', "Mo looks at a field of ploughed furrows. Near him the ridges are wide and clear, but far away they are tiny and close together. Which cue does this show?",
      "Texture gradient", ["Superimposition", "Relative size", "Height in the plane"],
      "The detail changing from coarse and clear to fine and smooth with distance is texture gradient."),
    M('Identifying cues', "In a photograph of a lake, a small boat and a large boat of the same type are shown. Eve decides the small boat is further away. Which cue is she using?",
      "Relative size", ["Superimposition", "Linear perspective", "Stereopsis"],
      "The boat that makes a smaller image is judged to be further away, assuming both are the same kind of object. That is relative size."),
    M('Explaining with cues', "Which answer best explains how linear perspective helps Jo judge the distance of a lorry on a long, straight road?",
      "The road edges converge towards the horizon, so a lorry near that point seems far away", ["The road is a cue, so the lorry must be far away from Jo", "The lorry is partly hidden, so it is far away from Jo", "The lorry looks smaller than the car, so it is far away from Jo"],
      "A strong answer names the cue, explains what is seen (converging edges) and links it to the judgement of distance."),
    M('Identifying cues', "In a scene, which of these would most clearly use superimposition to judge distance?",
      "A bus is partly hidden behind a shelter, so the bus is judged further away", ["A bus looks smaller than another bus, so it is judged further away", "The lines of the road meet far away, so the bus is far away", "The bus is drawn higher up the picture, so it is judged further"],
      "Superimposition depends on one object overlapping and hiding part of another.")
  ] };

  /* ---------- PSY-PER-06 Perceptual set ---------- */
  B['PSY-PER-06'] = { title: 'Perceptual set: why we see what we expect', items: [
    M('Defining perceptual set', "What is meant by ‘perceptual set’?",
      "A readiness to perceive things in a certain way", ["A fixed, inborn way of seeing that cannot change", "The way the eye focuses on near objects", "A set of depth cues used to judge distance"],
      "Perceptual set (Allport, 1955) is a mental readiness to perceive in a particular way, shaped by factors such as motivation, expectation, emotion and culture."),
    M('Defining perceptual set', "Perceptual set supports which view of perception?",
      "Top-down processing, where prior experience shapes what we see", ["Bottom-up processing, where only the stimulus matters and knowledge is not used", "Perception that is the same for everyone who looks at the same scene", "Perception that depends only on the eyes and not on the brain"],
      "Because what we perceive is influenced by what we already know and expect, perceptual set fits top-down (constructivist) views."),
    M('Identifying the factor', "Dan has skipped lunch. On a walk, he thinks a yellow smudge on a wall looks like a slice of pizza. Which factor affecting perceptual set is this?",
      "Motivation", ["Emotion", "Culture", "Expectation"],
      "Hunger is a need that makes relevant things (food) stand out. It is motivation, not emotion."),
    M('Identifying the factor', "Liam is waiting at the arrivals gate for his sister. He mistakes a stranger of similar height for her. Which factor is this?",
      "Expectation", ["Motivation", "Emotion", "Culture"],
      "Liam expects to see his sister, so his perception is biased towards seeing her in an ambiguous person. This is expectation."),
    M('Identifying the factor', "Ella is walking alone at night and feels nervous. She hears a rustle and sees a coat on a hook as a man standing in the corner. Which factor is this?",
      "Emotion", ["Motivation", "Expectation", "Culture"],
      "Her fear makes harmless things look threatening. Feelings influencing perception is emotion."),
    M('Identifying the factor', "A man who has lived all his life in a remote forest village struggles to see depth in a photograph of a city street. Which factor best explains this?",
      "Culture", ["Emotion", "Motivation", "Binocular depth"],
      "How we interpret pictures, including depth cues, depends on experiences in our culture. This links to Hudson (1960)."),
    M('Identifying the factor', "A thirsty hiker thinks a shiny rock in the distance is a pool of water. Which factor is this?",
      "Motivation", ["Expectation", "Emotion", "Culture"],
      "Thirst is a need that makes water-like things stand out, which is motivation."),
    M('Identifying the factor', "After hearing she has won a prize, Sia thinks the café’s colours are brighter than they were yesterday. Which factor is this?",
      "Emotion", ["Motivation", "Culture", "Expectation"],
      "Happiness can make things seem brighter. This is emotion influencing perception."),
    M('Identifying the factor', "In a list of letters, an ambiguous shape is read as a ‘B’, but in a list of numbers the same shape is read as ‘13’. Which factor is shown?",
      "Expectation, created by the context", ["Motivation, created by hunger and the need for food", "Emotion, created by fear of the dark or of danger", "Culture, created by pictures from different societies"],
      "The surrounding letters or numbers set an expectation that changes how the shape is read."),
    M('Classifying correctly', "A student describes hunger as an emotion that changes perception. Which correction is accurate?",
      "Hunger is a need, so it is motivation rather than emotion", ["Hunger is an expectation, not a need that people have", "Hunger is a cultural factor in perception", "Hunger does not affect perception at all"],
      "Common error: hunger and thirst are motivations (needs). Emotion refers to feelings such as fear or happiness."),
    M('Studies', "In Gilchrist and Nesberg (1952), what did hungry participants do?",
      "Rated pictures of food as brighter", ["Rated pictures of food as duller than other pictures", "Judged distance more accurately than non-hungry people", "Drew ambiguous shapes from memory after seeing labels"],
      "Gilchrist and Nesberg (1952) found that hungry participants rated food pictures as brighter, showing motivation affects perception."),
    M('Studies', "The ‘B/13’ ambiguous symbol was used by Bruner and Minturn (1955) to show the effect of…",
      "Expectation from context", ["Motivation from hunger", "Emotion from fear", "Culture from upbringing"],
      "The same symbol was read as a letter among letters and as a number among numbers, showing that expectation affects perception."),
    M('Studies', "Hudson (1960) is used as evidence that perceptual set is affected by…",
      "Culture, because depth cues in pictures are interpreted differently", ["Motivation, because hunger changes brightness ratings of food", "Emotion, because fear changes shape judgements", "Expectation, because context changes a letter into a number"],
      "Hudson’s work showed that experience in different cultures influences how people interpret depth cues in pictures."),
    X('Identifying the factor', "Which of these can create a perceptual set?",
      ["Motivation", "Expectation", "Emotion", "Culture"], ["Stereopsis", "Linear perspective"],
      "Motivation, expectation, emotion and culture all influence what we are ready to perceive. Stereopsis and linear perspective are depth cues, not factors in perceptual set."),
    M('Application', "A gardener shows two groups the same blurred picture. One group has just been told it is a photograph of an animal; the other is told it is a landscape. Most of each group describe what they were told. Which concept explains this?",
      "Perceptual set created by expectation", ["Size constancy", "Binocular disparity", "Texture gradient because detail changes with distance"],
      "What people were told set an expectation, so each group was ready to see the blurred picture in that way."),
    M('Application', "Two people see the same dark shape in a park. Zoe is afraid of dogs and says, ‘It’s a big dog.’ Her friend Ali loves dogs and sees it as a bush. Which factor most likely explains Zoe’s perception?",
      "Emotion, as her fear makes the shape look threatening", ["Culture, because dogs are common in her town", "Motivation, because she is hungry for food", "Expectation, because she was told about dogs beforehand"],
      "Fear makes harmless things look threatening. The question links emotion to Zoe’s changed perception."),
    M('Application', "A researcher asks children from a rich city and from a poor rural area to estimate the size of coins. The poorer children estimate larger sizes. Which factor is a likely explanation?",
      "Motivation, because money matters more to them", ["Culture, because coins are round", "Binocular disparity, because they use two eyes", "Linear perspective, because coins are flat"],
      "Valuing something highly can make it stand out and be perceived differently. The need or value for money is a motivational factor."),
    M('Explaining the concept', "Which answer best describes how expectation can affect perception?",
      "We see what we expect, so an ambiguous object is read to fit the context", ["We see everything exactly as it is, whatever the context we are in", "We see only things we are hungry for at the time", "We see only things from our own culture and nothing else"],
      "Context sets up expectations, so ambiguous information is interpreted to fit what we expect."),
    M('Explaining the concept', "Which answer best explains why Nell, a lifeguard, quickly spots a swimmer in trouble among people splashing at a pool?",
      "Her experience gives her a perceptual set for signs of trouble", ["She sees all swimmers exactly alike whatever they do", "She uses only stereopsis to judge swimmers", "Her perception never uses prior knowledge or training"],
      "Her expectations and training make her ready to notice particular signs. A full answer links the concept to the person."),
    M('Explaining the concept', "A friend says, ‘Perceptual set simply means people like looking at things.’ What is the best correction?",
      "A readiness to perceive in a certain way, shaped by motivation, expectation, emotion and culture", ["It is the way depth cues are used by one eye or by both", "It is the sensation that arrives at the retina from the object", "It is the tendency to see objects as the same size at any distance"],
      "Perceptual set concerns mental readiness shaped by experience and state. The other options describe different parts of the perception topic."),
    M('Neighbouring ideas', "Which of these is NOT a factor that affects perceptual set?",
      "Binocular disparity", ["Culture", "Motivation", "Emotion"],
      "Binocular disparity is a depth cue that uses two eyes. It is not a factor in perceptual set."),
    M('Studies', "In Gilchrist and Nesberg (1952), the hungry participants rated food pictures as brighter. Which conclusion does this support?",
      "Motivation can affect what we perceive", ["Culture has no effect on perception of any picture", "Hunger makes people see worse than they otherwise would", "Perception only depends on the object that is seen"],
      "Because hunger changed brightness ratings, the study supports the idea that motivation affects perception."),
    M('Application', "Carl is at a party looking for his friend Dee, who wears a red hat. All evening he keeps thinking he sees Dee, but each time it is a stranger in red. Which factor could explain Carl’s mistakes?",
      "Expectation, because he is ready to see Dee", ["Culture, because red is common in clothes", "Emotion, because he is always happy at parties", "Depth, because the room is large and full of people"],
      "Carl expects to see a person in a red hat, so he is ready to see Dee in similar-looking strangers. This is expectation."),
    M('Evaluation', "Which is a limitation of using perceptual set studies as evidence for top-down perception?",
      "Many were done in laboratories with artificial tasks", ["They all involved no participants in the studies", "They did not measure perception in any way", "They used only one eye to view the objects"],
      "Artificial tasks may not show how perception works in everyday life, so there is a question about real-life validity.")
  ] };

  /* ---------- PSY-PER-03 Illusions and constancies ---------- */
  var SV4 = '<svg viewBox="0 0 260 130" role="img" aria-label="Two horizontal lines of equal length. The top line has fins sloping back towards its middle at each end and the bottom line has fins sloping away from its middle at each end">' +
    '<rect x="0" y="0" width="260" height="130" fill="#ffffff" stroke="#9aa5b8"/>' +
    '<line x1="40" y1="40" x2="220" y2="40" stroke="#303a4c" stroke-width="3"/><line x1="40" y1="40" x2="60" y2="25" stroke="#303a4c" stroke-width="3"/><line x1="40" y1="40" x2="60" y2="55" stroke="#303a4c" stroke-width="3"/><line x1="220" y1="40" x2="200" y2="25" stroke="#303a4c" stroke-width="3"/><line x1="220" y1="40" x2="200" y2="55" stroke="#303a4c" stroke-width="3"/>' +
    '<line x1="40" y1="95" x2="220" y2="95" stroke="#303a4c" stroke-width="3"/><line x1="40" y1="95" x2="20" y2="80" stroke="#303a4c" stroke-width="3"/><line x1="40" y1="95" x2="20" y2="110" stroke="#303a4c" stroke-width="3"/><line x1="220" y1="95" x2="240" y2="80" stroke="#303a4c" stroke-width="3"/><line x1="220" y1="95" x2="240" y2="110" stroke="#303a4c" stroke-width="3"/>' +
    '<text x="130" y="20" font-size="12" text-anchor="middle" fill="#303a4c">Line P</text><text x="130" y="125" font-size="12" text-anchor="middle" fill="#303a4c">Line Q</text></svg>';
  var SV5 = '<svg viewBox="0 0 200 160" role="img" aria-label="A cube drawn as a wire frame with all edges visible, so that the front face could be either the lower left square or the upper right square">' +
    '<rect x="0" y="0" width="200" height="160" fill="#ffffff" stroke="#9aa5b8"/>' +
    '<g fill="none" stroke="#303a4c" stroke-width="3"><rect x="40" y="60" width="80" height="80"/><rect x="80" y="20" width="80" height="80"/><line x1="40" y1="60" x2="80" y2="20"/><line x1="120" y1="60" x2="160" y2="20"/><line x1="40" y1="140" x2="80" y2="100"/><line x1="120" y1="140" x2="160" y2="100"/></g></svg>';
  B['PSY-PER-03'] = { title: 'Visual illusions and visual constancies', items: [
    M('Defining terms', "What is meant by a ‘visual illusion’?",
      "When what we perceive does not match the physical object, so we are misled", ["When the eye cannot detect light", "When we see an object as unchanged as it moves", "When two people see the same image in the same way"],
      "A visual illusion is a mismatch between what is seen and what is actually there."),
    M('Defining terms', "What is meant by ‘visual constancy’?",
      "Seeing an object as keeping the same size, shape or colour even when its retinal image changes", ["Seeing an object as different from how it really is", "Seeing two different images in one picture", "Seeing something that is not there"],
      "Constancy keeps the world stable: objects look the same size, shape and colour despite changes in distance, angle or lighting."),
    M('Types of illusion', "A figure can be seen in two different ways, but only one at a time, and the percept flips between them. What is this type of illusion?",
      "An ambiguous figure", ["A distortion", "A fiction", "A constancy"],
      "Ambiguous figures such as the Necker cube, rabbit-duck and Rubin’s vase can be seen in two ways, but not both at once."),
    M('Types of illusion', "Which of these is an example of a distortion?",
      "The Müller-Lyer illusion", ["The Kanizsa triangle", "The Necker cube", "Rubin’s vase"],
      "Müller-Lyer, Ponzo and café wall are distortions: they make length, size or angle look different from reality."),
    M('Types of illusion', "The Kanizsa triangle makes people see a bright triangle that is not actually drawn. What type of illusion is this?",
      "A fiction", ["An ambiguous figure", "A distortion", "A constancy"],
      "Fictions make us see something that is not there, such as edges of the Kanizsa triangle."),
    M('Types of illusion', "Look at the figure. Lines P and Q are exactly the same length, but Q looks longer. What type of illusion is this?",
      "A distortion", ["A fiction", "An ambiguous figure", "A shape constancy"],
      "The Müller-Lyer illusion makes equal lines look different in length. Distortions change how long, big or sloped something appears.", { svg: SV4, family: 'per03-fig1' }),
    M('Types of illusion', "Look at the figure. The cube sometimes looks as if the lower left square is at the front and sometimes as if the upper right square is at the front. What type of illusion is this?",
      "An ambiguous figure", ["A distortion", "A fiction", "A colour constancy"],
      "The Necker cube can be seen in two ways, and the view flips between them. Only one is seen at a time.", { svg: SV5, family: 'per03-fig2' }),
    M('Types of illusion', "Sia is shown a drawing that makes her see a face, and then a vase, but never both at once. Which type of illusion is it?",
      "An ambiguous figure", ["A fiction", "A distortion", "A size constancy"],
      "Rubin’s vase is an ambiguous figure: the percept alternates between the two images."),
    M('Types of illusion', "Max looks at a picture of black shapes with small gaps and sees a white shape in the middle with clear edges, although nothing is drawn there. What type of illusion is this?",
      "A fiction", ["A distortion", "An ambiguous figure", "A shape constancy"],
      "Seeing contours or shapes that are not really there is a fiction."),
    M('Types of illusion', "Straight parallel lines in a pattern of black and white tiles look sloped, although they are not. Which type of illusion is this?",
      "A distortion", ["A fiction", "An ambiguous figure", "A colour constancy"],
      "The café wall illusion is a distortion: lines look sloped when they are parallel."),
    X('Types of illusion', "Which of these are distortions?",
      ["Müller-Lyer", "Ponzo", "Café wall"], ["Kanizsa triangle", "Necker cube"],
      "Müller-Lyer, Ponzo and café wall change apparent length, size or angle. Kanizsa is a fiction and the Necker cube is an ambiguous figure."),
    M('Misconceptions', "Which statement about ambiguous figures is correct?",
      "Only one reading is seen at a time, and the percept flips between them", ["Both readings are seen clearly at the same time", "Nothing is seen until a label is given", "They always show something that is not there"],
      "In ambiguous figures the brain switches between two readings, but cannot hold both at once."),
    M('Constancy', "Kiran watches a plane taking off. Even though the plane’s image on his eye gets smaller, he still sees it as the same size. Which constancy is this?",
      "Size constancy", ["Shape constancy", "Colour constancy", "A distortion"],
      "Perceiving objects as the same size even when the retinal image shrinks is size constancy."),
    M('Constancy', "Mae sees a book lying on a desk from many angles. Its image on her eye changes from rectangle to trapezium, but she still sees a rectangle. Which constancy is this?",
      "Shape constancy", ["Size constancy", "Colour constancy", "A fiction"],
      "Seeing an object as keeping its true shape despite changes in viewing angle is shape constancy. The opening door is a classic example."),
    M('Constancy', "A red apple looks red to Alba at noon outdoors and also in a dim kitchen in the evening. Which constancy allows this?",
      "Colour constancy", ["Size constancy", "Shape constancy", "A distortion"],
      "Colour constancy means an object is seen as the same colour under different lighting."),
    M('Constancy', "Why is colour constancy useful?",
      "We can recognise objects as the same colour in different levels of light", ["We can see objects that are not there", "We can see two images in one picture", "We can judge the length of lines accurately"],
      "Without colour constancy, objects would seem to change colour whenever the light changed, making them hard to recognise."),
    X('Constancy', "Which of these are visual constancies?",
      ["Size constancy", "Shape constancy", "Colour constancy"], ["Fictions", "Ambiguous figures"],
      "The three constancies are size, shape and colour. Fictions and ambiguous figures are types of visual illusion."),
    M('Constancy', "A cyclist rides away down a long road. People watching still see him as a normal-sized man rather than shrinking. Which term describes this?",
      "Size constancy", ["Relative size", "A distortion", "A fiction"],
      "Seeing him as unchanged in size is size constancy. It should not be confused with relative size, which is a depth cue."),
    M('Illusion or constancy', "Which of these is an example of a constancy rather than an illusion?",
      "A rotating wheel is still seen as a circle when it is viewed from the side", ["Two equal lines look different in length", "A shape appears with no lines to draw it", "A picture flips between a duck and a rabbit"],
      "A constancy is accurate: the object is seen as unchanged. The other options are illusions."),
    M('Illusion or constancy', "Which description is of a visual illusion rather than a constancy?",
      "Two parallel lines look sloped because of the pattern around them", ["A white shirt still looks white in dim light", "A door looks rectangular as it opens", "A friend walking away does not look as if he shrinks"],
      "The first is a distortion, where perception is misled. The others are constancies, which keep perception stable."),
    M('Application', "Norman is shown photographs of a door opened by different amounts. He says it is still a rectangle each time. Which concept explains this?",
      "Shape constancy", ["Size constancy", "A fiction", "Colour constancy"],
      "Seeing the door as a rectangle even though its image on the eye changes is shape constancy."),
    M('Application', "Rhys looks at a picture which a few viewers see as a young woman and others as an old woman, and some can switch between them. What do we call this type of picture?",
      "An ambiguous figure", ["A fiction", "A size constancy", "A distortion"],
      "Pictures that can be seen in two ways are ambiguous figures. Only one image is seen at once.")
  ] };

  /* ---------- PSY-PER-05 Gregory ---------- */
  B['PSY-PER-05'] = { title: "Gregory's constructivist theory of perception", items: [
    M('Core ideas', "According to Gregory (1970), perception is…",
      "Top-down: the brain builds what we see from input and knowledge", ["Bottom-up: the senses supply everything and no knowledge is used at all in what we see", "Fixed at birth, with experience having no effect on what is perceived", "Based only on how the eye focuses light"],
      "Gregory said perception is constructed. The brain combines the sensory input with stored knowledge and experience."),
    M('Core ideas', "What is a ‘perceptual hypothesis’ in Gregory’s theory?",
      "The brain’s best guess about what the sensory input shows", ["A scientist’s prediction about an experiment that tests a theory", "The light that falls on the retina from the object", "The feeling that an object is nearer than it is really"],
      "A perceptual hypothesis is the brain’s best guess, which is tested against the sensory input."),
    M('Core ideas', "Why does Gregory say we need to make inferences when we perceive?",
      "Input is often unclear, so the brain fills gaps", ["Sensory input is always perfect and the brain adds nothing extra to it", "Inferences are needed only for sounds and never for sights", "The eyes can detect everything without help from the brain"],
      "Because the information reaching the eye is often incomplete, the brain infers what is probably there."),
    M('Core ideas', "How does prior knowledge help in Gregory’s theory?",
      "It guides which hypothesis the brain chooses", ["It stops the brain forming hypotheses about the scene", "It changes the physical image on the retina of the eye", "It replaces sensory input completely"],
      "Past experience makes certain hypotheses more likely, helping the brain make sense of unclear input."),
    M('Core ideas', "Which statement explains why an ambiguous figure flips between two images, according to Gregory?",
      "Two hypotheses fit equally well, so the brain cannot settle", ["The brain sees both images clearly at the same time in the figure", "The eyes physically change the image every few seconds", "The brain has no hypothesis about the figure at any time"],
      "With two equally good hypotheses, the brain switches between them. Only one is seen at a time."),
    M('Application', "Joel sees a blurred photograph of a dark, four-legged shape and says, ‘That’s a dog.’ He has owned dogs all his life. Which part of Gregory’s theory best explains his answer?",
      "Prior knowledge guides the perceptual hypothesis", ["Optic flow gives him all the information that he needs", "Direct perception requires no inference at all", "The photograph is a three-dimensional scene of the world"],
      "Joel’s experience with dogs makes ‘dog’ the most likely hypothesis for an unclear input. That is prior knowledge guiding the hypothesis."),
    M('Application', "Hana first thinks a dark shape in her hallway is a cat, then realises it is a coat. Which explanation uses Gregory’s theory?",
      "Her first hypothesis was tested and rejected", ["She stopped using prior knowledge altogether", "Her eyes changed the size of the coat in the hallway", "Perception in the hallway was bottom-up only"],
      "A perceptual hypothesis is tested against the input. When it did not fit, Hana formed a better one."),
    M('Application', "Eli reads the sentence ‘The cat sat on the m_t’ with a letter missing, and instantly sees ‘mat’. Which of Gregory’s ideas does this show?",
      "The brain infers what is missing using prior knowledge", ["The brain relies only on sensory input from the page", "The brain cannot fill in missing information at all", "The text is a distortion of the retinal image in her eye"],
      "Missing information is filled by inference using what he knows about words."),
    M('Application', "Two people look at the same drawing. One has studied art for years and sees a hidden face at once; the other does not. Which explanation uses Gregory’s theory?",
      "Their different prior knowledge leads to different hypotheses", ["The art student’s eyes are different from the other person’s", "The second person’s brain does not use inference at all", "Both must see the face if the input is the same for them both"],
      "In Gregory’s theory, what we see depends on experience as well as input, so different knowledge gives different perceptions."),
    M('Application', "Marigold looks at a picture and sees a vase, then two faces, but never both. Using Gregory’s theory, which explanation is best?",
      "The brain keeps switching between two hypotheses", ["She is using direct perception of the picture", "Her prior knowledge is missing completely", "The faces are reversed by her eyes in the picture"],
      "The picture supports two hypotheses (vase or faces); the brain alternates between them."),
    M('Application', "A blurred photograph shows people crossing a busy street. Alex immediately says it is a crossing. Which statement is the best Gregory explanation?",
      "He combined unclear input with experience to form a hypothesis", ["He used optic flow to see it directly", "The image contained complete information for him to use", "He did not form a hypothesis about the scene"],
      "A full answer links the unclear input, prior experience and the hypothesis he formed."),
    M('Strengths', "Which is a strength of Gregory’s theory?",
      "It explains why we are fooled by visual illusions", ["It explains why newborns judge depth without experience", "It was tested in rich real-world scenes", "It does not depend on what people already know"],
      "Illusions can be explained as the brain forming a wrong hypothesis. The other options are not strengths."),
    M('Strengths', "Why is it a strength that Gregory’s theory can explain differences between people’s perceptions?",
      "It explains effects of expectation, culture and experience", ["It says perception is identical for everyone in the world", "It says experience never matters to perception", "It proves perception is bottom-up in every case"],
      "Because prior knowledge shapes the hypothesis, the theory can explain why experience, culture or expectation change what people see."),
    M('Weaknesses', "Which is a weakness of Gregory’s theory made by Gibson’s supporters?",
      "Illusions are artificial; real scenes hold richer information", ["Gregory ignored the role of experience in perception", "Gregory said perception is bottom-up only", "Gregory did not mention hypotheses in his theory"],
      "Critics say Gregory relied on artificial illusions. In real life the visual world gives plenty of information, so less guessing may be needed."),
    M('Weaknesses', "A baby only a few days old reacts to the edge of a table as if she can see it drops away. Why is this a problem for Gregory’s theory?",
      "She has little experience, yet the theory relies on experience", ["Babies have more experience than adults of the world", "The theory says depth is inborn in all babies", "Babies cannot form hypotheses at all, which supports the theory"],
      "If perception depends on experience, very young babies should not be able to perceive depth, yet some seem to. This is a weakness."),
    M('Neighbouring theories', "Which idea belongs to Gibson’s theory and NOT Gregory’s?",
      "Optic flow gives rich information, so little guessing is needed", ["The brain forms perceptual hypotheses", "Perception is top-down and uses knowledge", "Prior knowledge fills gaps in input using inference"],
      "Gibson’s direct perception uses optic flow in the real world. Hypotheses, top-down processing and inference are Gregory’s ideas."),
    M('Neighbouring theories', "Which of these is a top-down influence on perception?",
      "Expecting to see a friend in a crowd", ["The pattern of light landing on the retina", "The structure of the eyeball", "A bright flash of light"],
      "Top-down processing uses knowledge and expectation. The other options are about the stimulus itself."),
    X('Core ideas', "Which statements about Gregory’s theory are correct?",
      ["Perception is constructed from input and knowledge", "The brain forms perceptual hypotheses"], ["Perception is a direct reading of optic flow", "Ambiguous figures are seen in both ways at once", "Prior knowledge plays no role"],
      "Gregory’s top-down theory has the brain build hypotheses from input and prior knowledge. Optic flow belongs to Gibson, and ambiguous figures are only seen one way at a time."),
    M('Common misconceptions', "A student writes, ‘In an ambiguous figure, the brain sees both pictures together.’ What is wrong?",
      "Only one hypothesis is held at a time, so images alternate", ["Nothing, this is Gregory’s idea exactly", "The brain never switches between hypotheses", "Hypotheses are never involved in ambiguous figures"],
      "The brain switches between two hypotheses rather than seeing both at once."),
    M('Evaluation', "Which of these is an evaluation point rather than a description of Gregory’s theory?",
      "It explains illusions but may rely on artificial images", ["The brain makes inferences about what it sees", "Sensory input is often unclear or incomplete", "Perception depends on prior knowledge and experience"],
      "An evaluation point judges the theory’s strengths or weaknesses. The others describe what the theory says."),
    M('Evaluation', "A critic says, ‘Gregory’s theory is too dependent on experience.’ Which evidence best supports this criticism?",
      "Newborn babies show some depth perception", ["Adults are fooled by illusions on a page", "Ambiguous figures flip between two images", "Expectations alter what people see in a picture"],
      "If infants with hardly any experience can perceive depth, perception cannot depend only on past experience."),
    M('Application', "Sam walks in thick fog and sees a faint shape which he thinks is a lamp post. When he gets closer it is a person. Which statement uses Gregory’s theory?",
      "His first hypothesis was wrong and was revised", ["His eyes were not working properly that day", "Perception is never a guess about the world", "Optic flow gave him accurate information at first glance"],
      "The theory says the brain makes the best guess from limited input; with better information the hypothesis is revised.")
  ] };

  /* ---------- PSY-PER-07 Haber and Levin (2001) ---------- */
  B['PSY-PER-07'] = { title: 'Haber and Levin (2001): judging size and distance', items: [
    M('Aim and sample', "What was the aim of Haber and Levin (2001)?",
      "To test whether size and distance are judged independently", ["To test whether people judge distance better than speed in everyday settings", "To compare men and women at judging size and distance", "To test whether people prefer familiar objects to unfamiliar ones"],
      "The study looked at whether perceiving size and perceiving distance depend on separate processes."),
    M('Aim and sample', "Who took part in Haber and Levin (2001)?",
      "109 male undergraduate students", ["99 male undergraduate students", "109 school children of both genders", "119 adults of both genders"],
      "The sample was 109 male undergraduates, which is a limitation as it is not representative of women or other ages."),
    M('Procedure', "Haber and Levin (2001) divided the field into four quadrants. In how many of them were objects placed?",
      "Three", ["One", "Two", "Four"],
      "Objects were placed in three of the four quadrants of the outdoor field, at different distances."),
    M('Procedure', "Where did the objects in Haber and Levin (2001) appear?",
      "In an outdoor field, at different distances from the viewer", ["On a computer screen in a dark room with no other objects", "In a laboratory with the lights off for the whole task", "On a stage in front of an audience of other students"],
      "Objects were placed in an outdoor field at different distances from the participants."),
    M('Procedure', "Which three kinds of object were used in Haber and Levin (2001)?",
      "Familiar standard-size objects, familiar variable-size objects and unfamiliar shapes", ["Large, medium and small versions of one object placed in a line", "Photographs, drawings and sculptures of familiar scenes", "Living, moving and still objects in a laboratory"],
      "The study used familiar standard-size objects, familiar objects of variable size (token variants) and unfamiliar shapes."),
    M('Procedure', "In Haber and Levin (2001), what is a ‘token variant’ object?",
      "A familiar object whose size varies between examples", ["An object with a fixed standard size known to everyone", "An unfamiliar geometric shape made for the study", "An object hidden behind another at a distance"],
      "Token variants are familiar objects such as Christmas trees, which come in many sizes, so memory gives no single standard."),
    M('Procedure', "Which is the best example of a token-variant object?",
      "A Christmas tree", ["A standard-size item of sports equipment", "A made-up geometric shape", "A road marking of standard length"],
      "Christmas trees are familiar, but they vary in size, which makes them a token-variant object."),
    M('Procedure', "Which is the best example of a familiar object with a standard size?",
      "A regulation football", ["A Christmas tree", "A made-up geometric shape", "A garden shed"],
      "A regulation football has a set size that people know from memory, so it is a standard-size familiar object."),
    M('Findings', "What did Haber and Levin (2001) find about estimates of distance?",
      "They were accurate for all kinds of object", ["They were accurate only for familiar objects", "They were inaccurate for all kinds of object", "They were less accurate for objects further away"],
      "Distance estimates were accurate whatever the object type."),
    M('Findings', "For which type of object were size estimates most accurate in Haber and Levin (2001)?",
      "Familiar objects with a standard size", ["Unfamiliar geometric shapes made for the study", "Token-variant objects such as Christmas trees", "Objects in the closest quadrant of the field"],
      "People judged size accurately when they knew the object’s usual size from memory."),
    M('Findings', "Which pair of object types led to less accurate size estimates in Haber and Levin (2001)?",
      "Token-variant objects and unfamiliar shapes", ["Standard-size objects and token-variant objects", "Standard-size objects and unfamiliar shapes", "Only standard-size objects"],
      "When there is no single known size in memory (token variants or unfamiliar shapes), size estimates were less accurate."),
    M('Conclusion', "What did Haber and Levin (2001) conclude?",
      "Size is judged from memory of familiar objects, separately from distance", ["We judge size only by how far away something is from us", "We judge distance only from memory of object size alone", "We cannot judge size or distance accurately in any setting"],
      "Because distance estimates were accurate for all objects but size estimates depended on familiarity, size and distance appear to be judged separately."),
    M('Conclusion', "Why do the findings suggest size and distance are judged separately?",
      "Distance was judged well even when size judgements were poor", ["Both were equally poor for every object in the field", "Size judgements were poor because distance was poor as well", "Both were perfect for every object in the field"],
      "Accurate distance with inaccurate size for some objects suggests the two are not the same process."),
    X('Findings', "Which of these statements about the findings of Haber and Levin (2001) are correct?",
      ["Distance estimates were accurate for all types of object", "Size estimates were accurate for familiar standard-size objects"], ["Size estimates were accurate for unfamiliar shapes", "Distance estimates were poor for objects in far quadrants", "Women were more accurate than men"],
      "Distance was accurate for all objects and size was accurate for standard-size familiar objects. All participants were men, so no male and female comparison was made."),
    M('Application', "Ben estimates the height of a distant statue by comparing it with a standard-size red telephone box nearby. According to the findings, how accurate is he likely to be about the box’s size?",
      "Quite accurate, because the box is familiar and has a standard size", ["Inaccurate, because it is a token variant object", "Inaccurate, because it is an unfamiliar shape to him", "Inaccurate, because he is far away from the box"],
      "Standard-size familiar objects were judged accurately, so Ben’s estimate of the box would be good."),
    M('Application', "Priya sees an unusual sculpture made of metal cubes in a park and is asked how big it is. According to Haber and Levin (2001), which judgement is likely to be less accurate?",
      "Its size", ["Its distance", "Both its size and distance equally", "Neither its size nor distance"],
      "For unfamiliar shapes, size estimates were less accurate while distance estimates remained accurate."),
    M('Application', "A guide is asked how tall a tree in a forest is. Trees vary greatly in height. Based on the study, how accurate would size estimates for this tree be, compared with a standard-size object?",
      "Less accurate, because trees are familiar but vary in size", ["More accurate, because trees are familiar to everyone", "Equally accurate, because trees are living things", "More accurate, because trees are unfamiliar to guides"],
      "Trees are like token variants: familiar, but the size in memory varies, so size judgements are less accurate."),
    M('Application', "Tom guesses the distance to a distant lamp post and is quite accurate, but he cannot say how tall it is. Which finding matches his experience?",
      "Distance was accurate for all objects, but size was less accurate for some", ["Size estimates were more accurate than distance estimates for every object", "All estimates were inaccurate whatever the object", "Distance estimates were inaccurate for unfamiliar objects only"],
      "Haber and Levin (2001) found accurate distance judgements for all objects but less accurate size judgements for some."),
    M('Evaluation', "Which is a limitation of the sample used by Haber and Levin (2001)?",
      "All were male students, so results may not generalise to women", ["It was too small to carry out any analysis on the results", "It contained only children from one school", "It included participants who had not seen the objects before the task"],
      "A sample of 109 male undergraduates is not representative of the wider population."),
    M('Evaluation', "Which is a weakness of the setting of Haber and Levin (2001)?",
      "The task was artificial, so it may not reflect everyday judgements", ["It took place in a busy street in a city centre", "It used no objects at all in the field", "It involved no participants at all in the study"],
      "Estimating the size of placed objects in a field is not how people judge size in daily life, so ecological validity may be low."),
    M('Evaluation', "Which is a strength of Haber and Levin (2001)?",
      "Estimates could be compared with the real sizes and distances", ["It used a large and varied sample of men and women", "It was carried out in people’s homes at night", "It showed that distance is always judged wrongly by everyone"],
      "Because the objects were set up by the researchers, actual size and distance were known, so accuracy could be measured."),
    M('Evaluation', "Which of these is NOT a true detail of Haber and Levin (2001)?",
      "The participants were primary school children", ["The participants were undergraduates at a university", "Objects were in an outdoor field at different distances", "Three kinds of object were used in the study"],
      "The participants were 109 male undergraduate students, not children."),
    M('Evaluation', "Why might the results of Haber and Levin (2001) be less accurate for token-variant objects?",
      "Their size differs, so memory gives no single standard size", ["They were always further from participants than other objects", "They were less visible in the field than other objects", "Participants did not look at them during the task"],
      "Without a single known size in memory, participants could not use familiar size as a guide.")
  ] };

  /* ---------- PSY-PER-08 Carmichael, Hogan and Walter (1932) ---------- */
  B['PSY-PER-08'] = { title: 'Carmichael, Hogan and Walter (1932): words change what we see', items: [
    M('Aim and procedure', "What was the aim of Carmichael, Hogan and Walter (1932)?",
      "To see if a label changes how a picture is drawn later", ["To test whether people can draw from memory after a short delay", "To find out how many drawings people can remember correctly", "To compare drawings by artists and non-artists in a gallery"],
      "The study tested whether a word given with an ambiguous drawing alters how the figure is later reproduced."),
    M('Aim and procedure', "How many ambiguous line drawings were shown in Carmichael, Hogan and Walter (1932)?",
      "12", ["6", "10", "20"],
      "Participants were shown 12 ambiguous line drawings, one at a time."),
    M('Aim and procedure', "In Carmichael, Hogan and Walter (1932), what was the difference between the two lists of names?",
      "Each drawing had a different name per list, e.g. ‘eyeglasses’ or ‘dumbbells’", ["One list had names and the other showed no pictures to participants", "One list used words and the other used numbers for each drawing", "The same name was used on both lists for every drawing"],
      "The same ambiguous drawing was labelled with a different word on each list, so any difference in drawings could be linked to the label."),
    M('Aim and procedure', "What was the control group in Carmichael, Hogan and Walter (1932) given?",
      "No names for the drawings", ["Both lists of names", "A list of numbers", "Different drawings from the others"],
      "The control group saw the drawings without any verbal label, giving a baseline."),
    M('Aim and procedure', "What did participants do after seeing the drawings in Carmichael, Hogan and Walter (1932)?",
      "They redrew the figures from memory", ["They described the figures aloud", "They chose the correct figure from a set", "They named all the drawings without seeing them"],
      "Participants reproduced the figures from memory, and the drawings were then compared with the labels."),
    M('Findings', "What did Carmichael, Hogan and Walter (1932) find?",
      "About three quarters of labelled drawings looked like the label, against under half in the control group", ["Nearly all control group drawings looked like the named object on both of the lists", "The labelled groups drew the figures identically to the originals every time", "The label made no difference to any group of participants"],
      "The labels influenced reproduction: most labelled-group drawings moved towards the named object, whereas the control group’s did not."),
    M('Conclusion', "What was the conclusion of Carmichael, Hogan and Walter (1932)?",
      "Language when seeing affects how a form is drawn", ["Language has no effect on how a visual form is seen or drawn", "Visual memory is always perfect when words are used", "Drawings change the words people hear about a figure"],
      "Labels given with the figures affected how they were seen and later drawn."),
    M('Findings', "Which statement about Carmichael, Hogan and Walter (1932) is NOT correct?",
      "The labels changed the original pictures", ["Labels changed how the figures were reproduced", "A control group was used", "The task used ambiguous drawings"],
      "The pictures never changed. It was the participants’ perception and reproduction that changed."),
    X('Findings', "Which of these statements about Carmichael, Hogan and Walter (1932) are correct?",
      ["Participants redrew the figures from memory", "The labels were two different words per figure", "A group heard no label"], ["Every participant saw the same word for every drawing", "Participants drew while looking at the originals"],
      "There were two lists of different labels plus an unlabelled control, and participants drew from memory."),
    M('Research methods', "In Carmichael, Hogan and Walter (1932), which variable is the independent variable?",
      "The label given (list 1, list 2 or none)", ["How closely the drawing matched the label that was given", "The number of drawings shown to each person", "The time taken to draw each figure"],
      "The researchers changed which label was heard. How the drawings looked afterwards was measured, which makes it the dependent variable."),
    M('Research methods', "In Carmichael, Hogan and Walter (1932), what was the dependent variable?",
      "How closely the drawings resembled the named object", ["Which label list each participant heard during the study", "The number of ambiguous drawings shown in total", "The age of the participants in each group"],
      "The DV is what was measured: how far the reproduced drawings looked like the labelled object."),
    M('Research methods', "Why was a control group used in Carmichael, Hogan and Walter (1932)?",
      "To show how figures are drawn with no label", ["To make the task more difficult for everyone", "To test the participants’ eyesight before the task", "To provide a larger sample of drawings"],
      "The control group gives a baseline, so any extra similarity to the label in the other groups can be put down to the label."),
    M('Evaluation', "Which is a strength of Carmichael, Hogan and Walter (1932)?",
      "A control group and standard procedure make it replicable", ["The task was just like everyday perception of the world", "It used a very large sample of different cultures around the world", "It measured brain activity as people drew"],
      "A lab procedure with a control group is controlled and can be repeated. The task was artificial."),
    M('Evaluation', "Which is a weakness of Carmichael, Hogan and Walter (1932)?",
      "Drawing figures from memory is artificial", ["There was no standard procedure for the groups", "It had no comparison group of any kind", "It could not be replicated by other researchers"],
      "Redrawing line figures is unlike everyday seeing, so the findings may not apply to real life."),
    M('Evaluation', "A critic says the labels may have changed memory of the figure rather than how it was perceived. Why is this a valid point about the study?",
      "They drew from memory, so recall may have changed", ["The labels were not heard until after drawing had finished", "Participants never saw the figures before drawing", "The drawings were done at the same time as the labels were heard"],
      "Because participants redrew from memory, we cannot be sure whether perception or remembering was affected."),
    M('Evaluation', "Which evaluation point includes a judgement rather than a generic comment?",
      "A control group helps, but memory may have changed, not seeing", ["It was a lab study in a university", "It used drawings of ambiguous shapes", "It was done in 1932 long ago"],
      "A judgement explains the effect on the study’s conclusions. The other options only name features."),
    M('Application', "Max is told ‘This is a snake’ before seeing a wavy line, and later draws it with scales. Which study does this support, and why?",
      "Carmichael et al. (1932), because the label changed the drawing", ["Haber and Levin (2001), because size was judged from memory", "Gilchrist and Nesberg (1952), because he was hungry at the time", "Hudson (1960), because depth cues were involved in the task"],
      "A word heard with a shape led to a drawing closer to the word, matching the labelling effect."),
    M('Application', "Nora is shown a blob. Her friend calls it ‘a cloud’ and she later draws it with a fluffy outline. Which concept explains this?",
      "A verbal label influencing how the shape was drawn", ["Size constancy explains the effect of the word", "Stereopsis explains the effect of the word", "Colour constancy explains the effect of the word"],
      "The word changed how the ambiguous shape was seen and then reproduced, as in Carmichael, Hogan and Walter (1932)."),
    M('Application', "Kai replicates the study with modern ambiguous images and asks whether labels still affect drawings. Which feature should he keep to make a fair comparison?",
      "A labelled group and a control group with no labels", ["Only one group, all hearing a label about each figure", "Allowing participants to see the labels again while they draw", "Letting participants choose their own labels for each figure"],
      "To judge whether labels affect drawings he needs a baseline with no labels."),
    M('Application', "Ruth is told ‘a bird’ before seeing an ambiguous shape, while Tom is told ‘a leaf’ before seeing the same shape. Both later draw it from memory. Which prediction follows from the study?",
      "Ruth’s drawing will look more bird-like, Tom’s more leaf-like", ["Both drawings will look exactly like the original shape", "Neither drawing will be affected by the word they heard", "Both drawings will look more like a bird than a leaf"],
      "Carmichael, Hogan and Walter (1932) found that the label heard with an ambiguous figure moved later drawings towards the named object."),
    M('Link to theory', "Which view of perception is supported by Carmichael, Hogan and Walter (1932)?",
      "Top-down: language and ideas shape what we perceive", ["Bottom-up: the stimulus alone decides what is perceived", "Direct perception without any interpretation by the brain", "Perception is identical for everybody who sees the figure"],
      "Labels changed how the same stimulus was drawn, showing that something other than the stimulus (language) shapes perception."),
    M('Aim and procedure', "In Carmichael, Hogan and Walter (1932), why were ambiguous drawings used?",
      "They have two readings, so a label can steer the reading", ["They were easy to remember for everybody", "They had only one possible meaning for everyone", "They were too small to see clearly"],
      "An ambiguous figure supports two readings, so a label can steer which reading is formed.")
  ] };
})();
